class Qwen2_5_VLForConditionalGenerationPruning(Qwen2_5_VLForConditionalGeneration):
    # Disable flash_attn_2 auto-detection: flash_attn may not be installed;
    # use sdpa/eager instead (set via attn_implementation in from_pretrained).
    _supports_flash_attn_2 = False

    def __init__(self, config, pruning_method='vanilla', visual_token_num=-1):
        super().__init__(config)
        if pruning_method == 'fastv':
            self.model = FastVQwen2_5_VLModel(config, visual_token_num)
        elif pruning_method == 'sparsevlm':
            self.model = SparseVLMQwen2_5_VLModel(config, visual_token_num)
        elif pruning_method == 'tops_variant3':
            self.model = TOPSVariant3Qwen2_5_VLModel(config, visual_token_num)
        elif pruning_method == 'tops':
            self.model = TOPSQwen2_5_VLModel(config, visual_token_num)
        elif pruning_method == 'tops_2':
            self.model = TOPSQwen2_5_VLModel(config, visual_token_num, disable_stage2=True)
        elif pruning_method == 'tops_plus':
            # tops+: vision-encoder-side ToMe merge, then single-stage RDC (S2 disabled, like tops_2)
            self.model = TOPSQwen2_5_VLModel(config, visual_token_num, disable_stage2=True)
        elif pruning_method == 'dart':
            # DART (EMNLP'25): in-LLM 第K层 pivot+diversity 剪枝
            self.model = DARTQwen2_5_VLModel(config, visual_token_num, use_coverage=False)
        elif pruning_method == 'dart_coverage':
            # DART_coverage: DART 的 diversity 换成 SCOPE coverage
            self.model = DARTQwen2_5_VLModel(config, visual_token_num, use_coverage=True)
        elif pruning_method == 'apet':
            # ApET (two-stage): S1 merges ViT-side before the merger down to 3T/2,
            # S2 merges the visual span in-LLM down to T/2 after layer L//2.
            from .modeling_qwen2_5_vl_apet import ApETQwen2_5_VLModel
            self.model = ApETQwen2_5_VLModel(config, visual_token_num)
        elif pruning_method == 'cover_llm':
            # 纯 coverage 在 LLM 第 COVER_LLM_LAYER 层 in-LLM 剪枝 (无DART pivots)
            self.model = DARTQwen2_5_VLModel(config, visual_token_num, use_coverage=False, pure_cover=True)
        elif pruning_method == 'cover_prune_1':
            # COVER_Prune_1: 双阶段. S1(after-proj)=cls_attn×coverage, S2(LLM层12/16)=all_text_attn×coverage
            self.model = CoverPrune1Qwen2_5_VLModel(config, visual_token_num)
        elif pruning_method == 'cover_prune_2':
            # COVER_Prune_2: attn乘进coverage每一项(w_v=被覆盖token attn), 双阶段
            self.model = CoverPrune2Qwen2_5_VLModel(config, visual_token_num)
        elif pruning_method in ('cover_prune_1_proj', 'cover_prune_2_proj', 'cover_prune_2_projector_vit', 'scope_vit_origin',
                                'scope_vit_origin_raw', 'cover_prune_2_proj_raw', 'cover_prune_2_projector_vit_raw', 'cover_prune_2_projector_vit_raw_merge_first', 'cover_prune_2_projector_merge_first',
                                'mico_coverage_vit_proj', 'mico_coverage_proj', 'mico_s1', 'holov'):
            # 单阶段(only after-projector, 剪到target): cp1_proj=SCOPE(外加权), cp2_proj=内加权
            #   cover_prune_2_projector_vit: cp2_proj 但 coverage 相似度在 ViT 空间算 (cls_attn 不变)
            #   scope_vit_origin: SCOPE 原版, 外加权 + coverage 在 ViT 空间
            #   *_raw: cls_attn 不归一化(真SCOPE原始attn) 的对照版
            #   mico_coverage_vit_proj: inner CLS×coverage on pre-merger ViT, keep T, no LLM prune
            #   mico_coverage_proj: same selector on merger/projector output, keep T, no LLM prune
            self.model = Qwen2_5_VLModel(config)
        elif pruning_method in ('mico_coverage_vit_proj_llm_12', 'mico_coverage_vit_proj_llm_10',
                                'mico_coverage_vit_proj_llm_8', 'mico_coverage_vit_proj_llm_6', 'mico_coverage_proj_llm_12',
                                'mico_coverage_proj_llm_10', 'mico_coverage_proj_llm_8',
                                'mico_coverage_proj_llm_7', 'mico_coverage_proj_llm_6') or _is_mico(pruning_method):
            # Within each feature space, every K arm shares S1=2T;
            # K only moves the post-layer S2 cut at fixed average-T budget.
            from .modeling_qwen2_5_vl_coverprune2 import TOPS_SCHEDULE
            from vlmeval.vlm.mico_coverage_select import (
                mico_s2_keep,
                fastv_keep_after_k,
                llm12_pruning_layers,
            )
            # text_config is the 28-layer LLM; top-level num_hidden_layers on
            # Qwen2.5-VLConfig can be the vision tower and would break R.
            text_cfg = getattr(config, 'text_config', None)
            n_layers = (
                text_cfg.num_hidden_layers
                if text_cfg is not None and getattr(text_cfg, 'num_hidden_layers', None)
                else getattr(config, 'num_hidden_layers', 28)
            )
            t = int(visual_token_num)
            if _is_mico(pruning_method):
                # Strip an optional `_s1m<M>` ablation suffix before reading K,
                # so `..._llm_2_s1m4` still resolves to K=2.
                _kstr = pruning_method.rsplit('_s1m', 1)[0]
                k = int(_kstr.rsplit('_', 1)[1])
                if not 1 <= k < n_layers:
                    raise ValueError(f"H-ViT S2 K must be in [1, {n_layers - 1}], got {k}")
                # S1 keeps m*T here, so use the generalised identity
                # T*L = K*(m*T) + (L-K)*R (m=2 reproduces fastv_keep_after_k).
                s1m = _mico_s1_mult(pruning_method)
                s2 = {k: mico_s2_keep(t, n_layers, k, s1m)}
            elif pruning_method in ('mico_coverage_vit_proj_llm_10', 'mico_coverage_vit_proj_llm_8',
                                  'mico_coverage_vit_proj_llm_6', 'mico_coverage_proj_llm_10', 'mico_coverage_proj_llm_8',
                                  'mico_coverage_proj_llm_7', 'mico_coverage_proj_llm_6'):
                k = int(pruning_method.rsplit('_', 1)[1])
                s2 = {k: fastv_keep_after_k(t, n_layers, k, 2 * t)}
            else:
                s2 = llm12_pruning_layers(TOPS_SCHEDULE.get("7b", {}), t, n_layers)
            print(f"[{pruning_method}] S2={s2} (1-indexed post-layer cut, R=(T*L-K*m*T)/(L-K), L={n_layers})")
            self.model = CoverPrune2Qwen2_5_VLModel(
                config, visual_token_num, pruning_layers=s2,
                mico=_is_mico(pruning_method),
                dynamic_r=_is_mico(pruning_method),
                s1_mult=_mico_s1_mult(pruning_method),
            )
        elif pruning_method == 'cover_prune_3':
            # COVER_Prune_3: 内(每项乘被覆盖attn)外(乘候选自身attn)都乘, 双阶段
            self.model = CoverPrune3Qwen2_5_VLModel(config, visual_token_num)
        else:
            self.model = Qwen2_5_VLModel(config)

        self.pruning_method = pruning_method
        self.target_visual_token_num = visual_token_num  # Original target (never changes)
        self.visual_token_num = visual_token_num  # Runtime metric (gets updated by TOPS-Variant3/FastV)

    def forward(
        self,
        input_ids: Optional[torch.LongTensor] = None,
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        past_key_values: Optional[List[torch.FloatTensor]] = None,
        inputs_embeds: Optional[torch.FloatTensor] = None,
        labels: Optional[torch.LongTensor] = None,
        use_cache: Optional[bool] = None,
        output_attentions: Optional[bool] = None,
        output_hidden_states: Optional[bool] = None,
        return_dict: Optional[bool] = None,
        pixel_values: Optional[torch.Tensor] = None,
        pixel_values_videos: Optional[torch.FloatTensor] = None,
        image_grid_thw: Optional[torch.LongTensor] = None,
        video_grid_thw: Optional[torch.LongTensor] = None,
        rope_deltas: Optional[torch.LongTensor] = None,
        cache_position: Optional[torch.LongTensor] = None,
        second_per_grid_ts: Optional[torch.Tensor] = None,
    ) -> Union[Tuple, Qwen2_5_VLCausalLMOutputWithPast]:
        r"""
            labels (`torch.LongTensor` of shape `(batch_size, sequence_length)`, *optional*):
                Labels for computing the masked language modeling loss. Indices should either be in `[0, ...,
                config.vocab_size]` or -100 (see `input_ids` docstring). Tokens with indices set to `-100` are ignored
                (masked), the loss is only computed for the tokens with labels in `[0, ..., config.vocab_size]`.

        Returns:

        Example:

        ```python
        >>> from PIL import Image
        >>> import requests
        >>> from transformers import AutoProcessor, Qwen2_5_VLForConditionalGeneration

        >>> model = Qwen2_5_VLForConditionalGeneration.from_pretrained("Qwen/Qwen2.5-VL-7B-Instruct")
        >>> processor = AutoProcessor.from_pretrained("Qwen/Qwen2.5-VL-7B-Instruct")

        >>> messages = [
            {
                "role": "user",
                "content": [
                    {"type": "image"},
                    {"type": "text", "text": "What is shown in this image?"},
                ],
            },
        ]
        >>> url = "https://www.ilankelman.org/stopsigns/australia.jpg"
        >>> image = Image.open(requests.get(url, stream=True).raw)

        >>> text = processor.apply_chat_template(messages, tokenize=False, add_generation_prompt=True)
        >>> inputs = processor(text=[text], images=[image], vision_infos=[vision_infos])

        >>> # Generate
        >>> generate_ids = model.generate(inputs.input_ids, max_length=30)
        >>> tokenizer.batch_decode(generate_ids, skip_special_tokens=True, clean_up_tokenization_spaces=False)[0]
        "The image shows a street scene with a red stop sign in the foreground. In the background, there is a large red gate with Chinese characters ..."
        ```"""

        output_attentions = output_attentions if output_attentions is not None else self.config.output_attentions
        output_hidden_states = (
            output_hidden_states if output_hidden_states is not None else self.config.output_hidden_states
        )
        return_dict = return_dict if return_dict is not None else self.config.use_return_dict
        stage1_metadata = {}

        if inputs_embeds is None:
            inputs_embeds = self.model.get_input_embeddings()(input_ids)
            if pixel_values is not None:
                pixel_values = pixel_values.type(self.visual.dtype)

                if self.pruning_method in ['fastervlm', 'prumerge', 'prumerge+', 'visionzip', 'visionzip+', 'vispruner', 'tops_variant3', 'tops', 'tops_2', 'tops_plus', 'holov', 'cover_prune_1', 'cover_prune_2', 'cover_prune_3', 'cover_prune_1_proj', 'cover_prune_2_proj', 'cover_prune_2_projector_vit', 'scope_vit_origin', 'scope_vit_origin_raw', 'cover_prune_2_proj_raw', 'cover_prune_2_projector_vit_raw', 'cover_prune_2_projector_vit_raw_merge_first', 'cover_prune_2_projector_merge_first', 'tsvol_w', 'tsvol_w_anti', 'mico_coverage_vit_proj', 'mico_coverage_vit_proj_llm_12', 'mico_coverage_vit_proj_llm_10', 'mico_coverage_vit_proj_llm_8', 'mico_coverage_vit_proj_llm_6', 'mico_coverage_proj', 'mico_coverage_proj_llm_12', 'mico_coverage_proj_llm_10', 'mico_coverage_proj_llm_8', 'mico_coverage_proj_llm_7', 'mico_coverage_proj_llm_6'] or _is_mico_s1(self.pruning_method):
                    def forward_with_attn(
                        self,
                        hidden_states: torch.Tensor,
                        cu_seqlens: torch.Tensor,
                        rotary_pos_emb: Optional[torch.Tensor] = None,
                        position_embeddings: Optional[Tuple[torch.Tensor, torch.Tensor]] = None,
                    ) -> torch.Tensor:
                        # Memory debug: Start of attention forward
                        if MEMORY_DEBUG_ENABLED:
                            log_memory_stats("Attention Forward: Start", verbose=True)
                            log_tensor_info(hidden_states, "Input hidden_states")

                        seq_length = hidden_states.shape[0]
                        print(f"[DEBUG][TOPS][forward_with_attn] hidden_states: {hidden_states.shape}, dtype={hidden_states.dtype}")
                        q, k, v = self.qkv(hidden_states).reshape(seq_length, 3, self.num_heads, -1).permute(1, 0, 2, 3).unbind(0)
                        print(f"[DEBUG][TOPS][forward_with_attn] q: {q.shape}, k: {k.shape}, v: {v.shape}")

                        # Memory debug: After QKV projection
                        if MEMORY_DEBUG_ENABLED:
                            log_memory_stats("Attention Forward: After QKV projection", verbose=True)
                            print(f"  Q shape: {q.shape}, K shape: {k.shape}, V shape: {v.shape}")
                            print(f"  Dtype: {q.dtype}")

                        if position_embeddings is None:
                            logger.warning_once(
                                "The attention layers in this model are transitioning from computing the RoPE embeddings internally "
                                "through `rotary_pos_emb` (2D tensor of RoPE theta values), to using externally computed "
                                "`position_embeddings` (Tuple of tensors, containing cos and sin). In v4.54 `rotary_pos_emb` will be "
                                "removed and `position_embeddings` will be mandatory."
                            )
                            emb = torch.cat((rotary_pos_emb, rotary_pos_emb), dim=-1)
                            cos = emb.cos()
                            sin = emb.sin()
                        else:
                            cos, sin = position_embeddings
                        self.q, self.k = q.clone(), k.clone()
                        q, k = apply_rotary_pos_emb_flashatt(q.unsqueeze(0), k.unsqueeze(0), cos, sin)
                        q = q.squeeze(0)
                        k = k.squeeze(0)

                        max_seqlen = (cu_seqlens[1:] - cu_seqlens[:-1]).max().item()
                        attn_output = flash_attn_varlen_func(q, k, v, cu_seqlens, cu_seqlens, max_seqlen, max_seqlen).reshape(
                            seq_length, -1
                        )
                        attn_output = self.proj(attn_output)

                        # Memory debug: Before standard attention computation (for pruning methods)
                        if MEMORY_DEBUG_ENABLED:
                            log_memory_stats("Attention Forward: Before standard attention weights", verbose=True)

                        q, k = apply_rotary_pos_emb_vision(self.q, self.k, cos, sin)
                        q = q.transpose(0, 1)
                        k = k.transpose(0, 1)
                        print(f"[DEBUG][TOPS][forward_with_attn] q after RoPE+transpose: {q.shape}, k: {k.shape}")

                        # Memory debug: Validate attention memory requirements
                        seq_len = q.shape[1]

                        if MEMORY_DEBUG_ENABLED:
                            print(f"\n!!! Computing attention weights for pruning !!!")
                            print(f"  Q shape after transpose: {q.shape}")
                            print(f"  K shape after transpose: {k.shape}")
                            print(f"  Sequence length: {seq_len}")
                            estimated_gb = validate_attention_memory(q.shape, k.shape, dtype=q.dtype, location="VisionZip Attention")

                        # Check if this is a multi-image sequence (e.g., consecutive images in HallusionBench)
                        SINGLE_IMAGE_TOKENS = 1296  # Standard Qwen2.5-VL tokens per image (36x36 grid)
                        MAX_SEQ_LEN_FOR_FULL_ATTENTION = 5000  # GPU memory limit

                        # Ground truth: one real segment per image, straight from cu_seqlens.
                        # The old `seq_len // 1296` heuristic misread ONE large wide image
                        # (e.g. wide ChartQA charts) as several images and split it into fake
                        # sub-images, so `image_attns` came out the wrong length and the
                        # downstream reshape/selection crashed (or silently scored garbage).
                        _seg_lens = (cu_seqlens[1:] - cu_seqlens[:-1]).tolist()
                        real_num_images = len(_seg_lens)
                        estimated_num_images = real_num_images
                        tokens_per_image = seq_len / max(real_num_images, 1)
                        # Only the memory guard should force per-image splitting; the image
                        # count itself is never guessed now.
                        is_likely_multi_image = real_num_images > 1

                        if is_likely_multi_image:
                            print(f"\n📸 Detected multi-image sequence: {real_num_images} images "
                                  f"(cu_seqlens lens={_seg_lens})")
                            print(f"  Sequence length: {seq_len} tokens")
                            print(f"  Estimated tokens per image: {tokens_per_image:.1f}")

                        if seq_len > MAX_SEQ_LEN_FOR_FULL_ATTENTION:
                            print(f"\n⚠️  WARNING: Sequence length {seq_len} exceeds maximum {MAX_SEQ_LEN_FOR_FULL_ATTENTION}")

                            # For multi-image sequences, use per-image attention
                            if is_likely_multi_image:
                                print(f"  Processing as {real_num_images} separate images to avoid OOM")

                                # Real per-image token counts from cu_seqlens (not a heuristic).
                                all_attn_weights = []
                                offset = 0
                                for seg in _seg_lens:
                                    start = offset
                                    end = offset + int(seg)
                                    offset = end
                                    if end > start:
                                        q_img = q[:, start:end, :]
                                        k_img = k[:, start:end, :]

                                        # Compute attention for this image only
                                        attn_img = torch.matmul(q_img, k_img.transpose(1, 2)) / math.sqrt(q.shape[-1])
                                        attn_img = torch.nn.functional.softmax(attn_img, dim=-1)
                                        all_attn_weights.append(attn_img)

                                # Instead of creating full block-diagonal matrix, store individual blocks
                                # and create a compressed representation for pruning selection
                                # This avoids allocating the full 65136×65136 matrix

                                print(f"  Creating compressed attention representation for {len(all_attn_weights)} images")

                                # For pruning purposes, we need to aggregate attention across images
                                # Option 1: Average attention patterns across all images
                                # Option 2: Keep max attention values across all images
                                # Option 3: Store blocks separately and process during pruning

                                # Using Option 1: Average attention patterns (most memory efficient)
                                # Each image has roughly the same number of tokens, so we can average
                                num_heads = all_attn_weights[0].shape[0]

                                # Find the maximum dimension among all attention blocks
                                max_dim = max(w.shape[-1] for w in all_attn_weights)

                                # Create averaged attention pattern
                                avg_attn = torch.zeros(num_heads, max_dim, max_dim, device=q.device, dtype=q.dtype)

                                for attn_block in all_attn_weights:
                                    block_size = attn_block.shape[-1]
                                    avg_attn[:, :block_size, :block_size] += attn_block

                                avg_attn = avg_attn / len(all_attn_weights)

                                # Store the averaged pattern - this will be used for pruning decisions
                                # The actual attention computation in forward pass will still handle images separately
                                self.attn_weights = avg_attn

                                # Also store the individual blocks for later use if needed
                                self.attn_blocks = all_attn_weights
                                self.num_images = estimated_num_images

                                print(f"  Compressed attention: {avg_attn.shape} (from {seq_len}×{seq_len})")
                                print(f"  Memory saved: ~{(seq_len * seq_len - max_dim * max_dim) * 2 / 1024**3:.2f} GB")

                            else:
                                # Fallback: Use lightweight probe for non-standard sequences
                                print(f"  Using lightweight attention probe for non-standard sequence")
                                q_probe = q.mean(dim=1, keepdim=True)
                                attn_scores = torch.matmul(q_probe, k.transpose(1, 2)) / math.sqrt(q.shape[-1])
                                attn_weights = torch.nn.functional.softmax(attn_scores, dim=-1)
                                self.attn_weights = attn_weights.expand(-1, seq_len, -1)

                            if MEMORY_DEBUG_ENABLED:
                                log_memory_stats("After multi-image attention computation", verbose=True)
                        else:
                            if MEMORY_DEBUG_ENABLED:
                                print(f"  Attempting to allocate full attention matrix...")

                            try:
                                attn_weights = torch.matmul(q, k.transpose(1, 2)) / math.sqrt(q.shape[-1])

                                # Memory debug: After attention matmul
                                if MEMORY_DEBUG_ENABLED:
                                    log_memory_stats("Attention Forward: After attention matmul", verbose=True)
                                    log_tensor_info(attn_weights, "Attention weights matrix")

                                attn_weights = torch.nn.functional.softmax(attn_weights, dim=-1)
                                self.attn_weights = attn_weights
                                print(f"[DEBUG][TOPS][forward_with_attn] attn_weights (standard): {attn_weights.shape}")

                            except torch.cuda.OutOfMemoryError as e:
                                if MEMORY_DEBUG_ENABLED:
                                    print(f"\n{'!'*70}")
                                    print(f"!!! OOM at attention weight computation !!!")
                                    print(f"{'!'*70}")
                                    print(f"  Tried to compute: {q.shape} @ {k.shape}.T")
                                    print(f"  Expected shape: [{q.shape[0]}, {q.shape[1]}, {k.shape[1]}]")
                                    log_memory_stats("OOM Details", show_tensors=True, verbose=True)
                                raise e

                        return attn_output
                    self.visual.blocks[-1].attn.forward = types.MethodType(forward_with_attn, self.visual.blocks[-1].attn)

                if (self.pruning_method in ('mmtok', 'mmtok_origin', 'cover_prune_2_projector_vit', 'scope_vit_origin', 'cover_prune_2_projector_vit_raw', 'scope_vit_origin_raw', 'cover_prune_2_projector_vit_raw_merge_first', 'mico_coverage_vit_proj', 'mico_coverage_vit_proj_llm_12', 'mico_coverage_vit_proj_llm_10', 'mico_coverage_vit_proj_llm_8', 'mico_coverage_vit_proj_llm_6', 'apet') or _is_mico_s1(self.pruning_method)) and not getattr(self, '_mmtok_hook_set', False):
                    # MMTok Q / cp2proj_vit / scope_vit_origin coverage 用 ViT 合并前特征: forward_pre_hook 捕获 merger 输入 [seq,1280]
                    def _cap_merger_in(mod, inp):
                        self._mmtok_merger_in = inp[0]
                    self.visual.merger.register_forward_pre_hook(_cap_merger_in)
                    self._mmtok_hook_set = True

                image_embeds = self.visual(pixel_values, grid_thw=image_grid_thw)

                if self.pruning_method in ['fastervlm', 'vispruner']:
                    attn_weights = self.visual.blocks[-1].attn.attn_weights

                    seq_length = pixel_values.shape[0]
                    window_index, _ = self.visual.get_window_index(image_grid_thw)
                    reverse_indices = torch.argsort(window_index)
                    if attn_weights.dim() == 2:
                        attn_weights = attn_weights.unsqueeze(0)      # [1, t, t] (mean-probe path)
                    if self.pruning_method == 'vispruner':
                        # [heads, queries, keys]: preserve keys as token relevance.
                        # Averaging softmax's key axis would make every score 1/N.
                        if attn_weights.shape[-1] == seq_length:
                            patch_scores = attn_weights.mean(dim=(0, 1))
                        else:
                            # Long multi-image inputs store each attention block;
                            # their padded average cannot recover per-image scores.
                            blocks = getattr(self.visual.blocks[-1].attn, 'attn_blocks', [])
                            if sum(block.shape[-1] for block in blocks) != seq_length:
                                raise ValueError('VisPruner attention blocks do not match this image sequence')
                            patch_scores = torch.cat([block.mean(dim=(0, 1)) for block in blocks])
                        # The ViT already packs each merger's four patches together,
                        # then reorders groups by window_index; restore output order.
                        image_attns = patch_scores.reshape(-1, self.visual.spatial_merge_unit).mean(-1)
                        image_attns = image_attns[reverse_indices]
                    else:
                        patch_scores = attn_weights.mean(dim=0).mean(dim=-1)
                        per_image = []
                        offset = 0
                        for thw in image_grid_thw:
                            _, H, W = int(thw[0].item()), int(thw[1].item()), int(thw[2].item())
                            t = H * W
                            Ht, Wt = H // 2, W // 2
                            blk = patch_scores[offset:offset + t].view(Ht, 2, Wt, 2).mean(dim=(1, 3)).reshape(Ht * Wt)
                            wi, _ = self.visual.get_window_index(thw.unsqueeze(0))
                            blk = blk[torch.argsort(wi)]
                            per_image.append(blk)
                            offset += t
                        image_attns = torch.cat(per_image)
                elif self.pruning_method in ['prumerge', 'prumerge+', 'visionzip', 'visionzip+']:
                    attn_keys = self.visual.blocks[-1].attn.k
                    attn_weights = self.visual.blocks[-1].attn.attn_weights

                    # Check if we have multi-image compressed representation
                    if hasattr(self.visual.blocks[-1].attn, 'num_images') and self.visual.blocks[-1].attn.num_images > 1:
                        # For multi-image sequences, we have averaged attention pattern
                        # Process it as if it's for a single image of that size
                        print(f"  Processing compressed multi-image attention for pruning")
                        avg_seq_length = attn_weights.shape[-1]

                        # The averaged attention already represents the typical pattern
                        # We can use it directly for pruning decisions
                        if avg_seq_length % 4 == 0:
                            image_attns = attn_weights.view(-1, avg_seq_length // 4, 4, avg_seq_length // 4, 4).mean(dim=(2, 4))
                        else:
                            # Fallback if dimensions don't align perfectly
                            image_attns = attn_weights

                        # For keys, we also need to handle the multi-image case
                        # Use the first portion of keys as representative
                        if attn_keys.shape[0] > avg_seq_length:
                            attn_keys_subset = attn_keys[:avg_seq_length, :, :]
                        else:
                            attn_keys_subset = attn_keys

                        if attn_keys_subset.shape[0] % 4 == 0:
                            image_keys = attn_keys_subset.view(attn_keys_subset.shape[0] // 4, 4, attn_keys_subset.shape[1], attn_keys_subset.shape[2]).mean(dim=1)
                        else:
                            # Fallback: use stride sampling
                            image_keys = attn_keys_subset[::4, :, :]
                    else:
                        # Standard single-image or manageable sequence processing
                        seq_length = pixel_values.shape[0]
                        window_index, _ = self.visual.get_window_index(image_grid_thw)
                        reverse_indices = torch.argsort(window_index)
                        image_attns = attn_weights.view(-1, seq_length // 4, 4, seq_length // 4, 4).mean(dim=(2, 4))
                        image_attns = image_attns[:, reverse_indices, :][:, :, reverse_indices]
                        image_keys = attn_keys.view(seq_length // 4, 4, attn_keys.shape[1], attn_keys.shape[2]).mean(dim=1)
                        image_keys = image_keys[reverse_indices, :, :]
                elif self.pruning_method in [
                    'tops', 'tops_2', 'tops_plus', 'tops_variant3', 'holov', 'cover_prune_1', 'cover_prune_2', 'cover_prune_3', 'cover_prune_1_proj', 'cover_prune_2_proj', 'cover_prune_2_projector_vit', 'scope_vit_origin', 'scope_vit_origin_raw', 'cover_prune_2_proj_raw', 'cover_prune_2_projector_vit_raw', 'cover_prune_2_projector_vit_raw_merge_first', 'cover_prune_2_projector_merge_first',
                    'tsvol_w', 'tsvol_w_anti', 'mico_coverage_vit_proj', 'mico_coverage_vit_proj_llm_12', 'mico_coverage_vit_proj_llm_10', 'mico_coverage_vit_proj_llm_8', 'mico_coverage_vit_proj_llm_6', 'mico_coverage_proj', 'mico_coverage_proj_llm_12', 'mico_coverage_proj_llm_10', 'mico_coverage_proj_llm_8', 'mico_coverage_proj_llm_7', 'mico_coverage_proj_llm_6',
                ] or _is_mico_s1(self.pruning_method):
                    attn_last = self.visual.blocks[-1].attn

                    if hasattr(attn_last, 'num_images') and attn_last.num_images > 1:
                        # Multi-image: collect all patch-level scores, then split by actual
                        # image boundaries from image_grid_thw and do proper 2×2 merge.
                        # H and W in image_grid_thw are always even (Qwen2.5-VL guarantees this),
                        # so H*W is always divisible by 4.
                        # Patches are in window_index order, so groups of 4 consecutive patches
                        # correspond to spatially adjacent 2×2 blocks — same as PatchMerger.
                        all_patch_scores = []
                        for attn_block in attn_last.attn_blocks:
                            # [num_heads, t_approx, t_approx] → mean over heads and cols → [t_approx]
                            all_patch_scores.append(attn_block.mean(dim=0).mean(dim=0))
                        all_patch_scores = torch.cat(all_patch_scores)  # [total_patches_approx]
                        print(f"[DEBUG][TOPS][tops/tops_variant3] all_patch_scores: {all_patch_scores.shape}")

                        token_scores = []
                        offset = 0
                        for thw in image_grid_thw:
                            _, H, W = thw[0].item(), thw[1].item(), thw[2].item()
                            t = H * W  # actual patch count, always divisible by 4
                            img_scores = all_patch_scores[offset:offset + t]  # [H*W]
                            # 2×2 spatial merge: groups of 4 consecutive = 1 token (window_index order)
                            img_token_scores = img_scores.view(-1, 4).mean(dim=1)  # [H*W//4], window order
                            # Restore to spatial order to align with image_embeds (which is in spatial order)
                            win_idx, _ = self.visual.get_window_index(thw.unsqueeze(0))
                            rev_idx = torch.argsort(win_idx)
                            img_token_scores = img_token_scores[rev_idx]
                            print(f"[DEBUG][TOPS][tops/tops_variant3] image H={H} W={W} patches={t} tokens={img_token_scores.shape[0]}")
                            token_scores.append(img_token_scores)
                            offset += t

                        image_attns = torch.cat(token_scores)  # [N]
                        print(f"[DEBUG][TOPS][tops/tops_variant3] image_attns (multi-image): {image_attns.shape}, N={image_embeds.shape[0]}")
                    else:
                        seq_length = pixel_values.shape[0]
                        attn_weights = attn_last.attn_weights
                        print(f"[DEBUG][TOPS][tops/tops_variant3] attn_weights (single-image): {attn_weights.shape}, seq_length={seq_length}")
                        window_index, _ = self.visual.get_window_index(image_grid_thw)
                        reverse_indices = torch.argsort(window_index)
                        image_attns = attn_weights.view(-1, seq_length // 4, 4, seq_length // 4, 4).mean(dim=(2, 4))
                        image_attns = image_attns[:, reverse_indices, :][:, :, reverse_indices]
                        print(f"[DEBUG][TOPS][tops/tops_variant3] image_attns (single-image, after window restore): {image_attns.shape}")
                elif self.pruning_method in ['trim_mean', 'trim_max', 'cdpruner_mean', 'cdpruner_max', 'tsvol', 'tsvol_w', 'tsvol_anti', 'tsvol_w_anti']:
                    image_token_indices = torch.where(input_ids == self.config.image_token_id)[1]

                # Generate selection mask
                N, D = image_embeds.shape
                device = image_embeds.device
                selected_masks = torch.ones(N, dtype=torch.bool, device=device)

                if self.pruning_method in ('random', 'rand'):
                    random_scores = torch.rand(N).to(device)
                    selected_indices = random_scores.topk(self.target_visual_token_num, dim=-1).indices

                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[selected_indices] = True
                elif self.pruning_method == 'fastervlm':
                    image_attns = image_attns.mean(dim=1).mean(dim=0)
                    selected_indices = image_attns.topk(self.target_visual_token_num, dim=-1).indices

                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[selected_indices] = True
                elif self.pruning_method == 'prumerge' or self.pruning_method == 'prumerge+':
                    image_keys = image_keys.mean(dim=1)
                    image_attns = image_attns.mean(dim=1).mean(dim=0)

                    if self.pruning_method == 'prumerge':
                        selected_indices = image_attns.topk(self.target_visual_token_num, dim=-1).indices
                    elif self.pruning_method == 'prumerge+':
                        arithmetic_step = int(N / self.target_visual_token_num * 2)
                        arithmetic_indices = torch.linspace(arithmetic_step//2, N-1-arithmetic_step//2,
                                                            self.target_visual_token_num//2, dtype=torch.long, device=device)
                        image_attns[arithmetic_indices] = 0
                        selected_indices = image_attns.topk(self.target_visual_token_num//2, dim=-1).indices
                        selected_indices = torch.cat([selected_indices, arithmetic_indices])

                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[selected_indices] = True
                    pruned_indices = selected_masks.float().topk(N-self.target_visual_token_num, dim=-1, largest=False).indices

                    selected_embeds = image_embeds[selected_indices]
                    selected_keys = image_keys[selected_indices]
                    selected_attns = image_attns[selected_indices]
                    pruned_embeds = image_embeds[pruned_indices]
                    pruned_keys = image_keys[pruned_indices]
                    pruned_attns = image_attns[pruned_indices]

                    selected_keys_norm = selected_keys / selected_keys.norm(dim=-1, keepdim=True)
                    pruned_keys_norm = pruned_keys / pruned_keys.norm(dim=-1, keepdim=True)

                    updated_embeds = torch.zeros_like(selected_embeds)
                    for i in range(updated_embeds.shape[0]):
                        center_key_norm = selected_keys_norm[i]
                        other_keys_norm = torch.cat([
                            selected_keys_norm[:i],
                            selected_keys_norm[i+1:],
                            pruned_keys_norm])

                        similarity = torch.matmul(center_key_norm, other_keys_norm.t())
                        cluster_indices = similarity.topk(32, dim=-1).indices

                        other_embeds = torch.cat([
                            selected_embeds[:i],
                            selected_embeds[i+1:],
                            pruned_embeds])
                        other_attns = torch.cat([
                            selected_attns[:i],
                            selected_attns[i+1:],
                            pruned_attns])

                        cluster_embeds = other_embeds[cluster_indices]
                        cluster_weights = other_attns[cluster_indices].unsqueeze(-1)

                        cluster_avg = torch.sum(cluster_embeds * cluster_weights, dim=0)
                        cluster_center = selected_embeds[i] + cluster_avg
                        updated_embeds[i] = cluster_center
                    image_embeds[selected_indices] = updated_embeds
                elif self.pruning_method == 'visionzip' or self.pruning_method == 'visionzip+':
                    # Memory debug: Start of VisionZip processing
                    if MEMORY_DEBUG_ENABLED:
                        log_memory_stats("VisionZip: Start", verbose=True)
                        print(f"  Image embeds shape: {image_embeds.shape}")
                        print(f"  Target visual tokens: {self.target_visual_token_num}")
                        print(f"  Total tokens N: {N}")

                    if self.pruning_method == 'visionzip':
                        dominant_token_num = int(self.target_visual_token_num * 27 / 32)
                        contextual_token_num = self.target_visual_token_num - dominant_token_num
                    elif self.pruning_method == 'visionzip+':
                        contextual_token_num = int(N * 5 / 100)
                        dominant_token_num = self.target_visual_token_num - contextual_token_num

                    # Ensure at least some dominant tokens
                    dominant_token_num = max(1, min(dominant_token_num, N))
                    contextual_token_num = max(0, min(contextual_token_num, N - dominant_token_num))

                    if MEMORY_DEBUG_ENABLED:
                        print(f"  Dominant tokens: {dominant_token_num}")
                        print(f"  Contextual tokens: {contextual_token_num}")

                    # Memory debug: Before dominant selection
                    if MEMORY_DEBUG_ENABLED:
                        log_memory_stats("VisionZip: Before dominant selection", verbose=True)
                        print(f"  Image_attns shape before reduction: {image_attns.shape}")

                    image_attns = image_attns.mean(dim=1).mean(dim=0)

                    if MEMORY_DEBUG_ENABLED:
                        print(f"  Image_attns shape after reduction: {image_attns.shape}")
                        print(f"  Image_embeds N: {N}")
                        print(f"  Dominant_token_num: {dominant_token_num}")

                    dominant_indices = image_attns.topk(dominant_token_num, dim=-1).indices

                    # Validate indices are within bounds
                    if MEMORY_DEBUG_ENABLED:
                        print(f"  Dominant_indices shape: {dominant_indices.shape}")
                        print(f"  Dominant_indices max: {dominant_indices.max()}")
                        print(f"  Dominant_indices min: {dominant_indices.min()}")

                    # Safety check: ensure indices are within valid range
                    if dominant_indices.max() >= N:
                        print(f"  WARNING: Index out of bounds detected!")
                        print(f"    Max index: {dominant_indices.max()}, but N={N}")
                        print(f"    Image_attns size: {image_attns.shape[0]}")
                        print(f"    Clamping indices to [0, {N-1}]")
                        dominant_indices = torch.clamp(dominant_indices, 0, N - 1)

                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[dominant_indices] = True

                    # Memory debug: After dominant selection
                    if MEMORY_DEBUG_ENABLED:
                        log_memory_stats("VisionZip: After dominant selection", verbose=True)
                        print(f"  Selected {dominant_indices.shape[0]} dominant tokens")

                    # If no contextual tokens needed, skip merging
                    if contextual_token_num == 0:
                        if MEMORY_DEBUG_ENABLED:
                            print(f"  No contextual tokens needed, skipping merge")
                    else:
                        # Re-verify N matches current image_embeds (in case of modifications)
                        actual_N = image_embeds.shape[0]
                        if actual_N != N:
                            print(f"  WARNING: image_embeds shape changed!")
                            print(f"    Original N: {N}")
                            print(f"    Current N: {actual_N}")
                            print(f"    Recreating selected_masks with correct size")
                            # Recreate selected_masks with correct size
                            old_mask = selected_masks
                            selected_masks = torch.zeros(actual_N, dtype=torch.bool, device=device)
                            # Copy over the valid indices
                            copy_len = min(old_mask.shape[0], actual_N)
                            selected_masks[:copy_len] = old_mask[:copy_len]
                            N = actual_N

                        # Validate selected_masks shape before filtering
                        if MEMORY_DEBUG_ENABLED:
                            print(f"  Selected_masks shape: {selected_masks.shape}")
                            print(f"  Selected_masks sum (selected tokens): {selected_masks.sum()}")
                            print(f"  Image_embeds shape: {image_embeds.shape}")

                        # Safety check: ensure mask and embeddings have matching dimensions
                        if selected_masks.shape[0] != image_embeds.shape[0]:
                            print(f"  ERROR: Shape mismatch!")
                            print(f"    selected_masks length: {selected_masks.shape[0]}")
                            print(f"    image_embeds length: {image_embeds.shape[0]}")
                            raise RuntimeError(f"VisionZip mask shape {selected_masks.shape[0]} doesn't match embeds shape {image_embeds.shape[0]}")

                        # Use image_embeds for filtering (not downsampled image_keys)
                        # This matches InternVL3 implementation
                        filtered_embeds = image_embeds[~selected_masks]

                        # Check if we have any filtered embeddings
                        if filtered_embeds.shape[0] == 0:
                            if MEMORY_DEBUG_ENABLED:
                                print(f"  No filtered embeddings available, skipping merge")
                        else:
                            normalized_embeds = filtered_embeds / filtered_embeds.norm(dim=-1, keepdim=True)

                            if MEMORY_DEBUG_ENABLED:
                                print(f"  Filtered embeds shape: {filtered_embeds.shape}")
                                print(f"  Normalized embeds shape: {normalized_embeds.shape}")

                            # Adjust contextual_token_num if needed
                            contextual_token_num = min(contextual_token_num, normalized_embeds.shape[0])
                            if contextual_token_num == 0:
                                if MEMORY_DEBUG_ENABLED:
                                    print(f"  Adjusted contextual tokens to 0, skipping merge")
                            else:
                                # Select contextual tokens evenly spaced
                                target_step = max(1, normalized_embeds.shape[0] // contextual_token_num)
                                target_indices = torch.arange(0, normalized_embeds.shape[0], target_step, device=device)[:contextual_token_num]
                                target_embeds = normalized_embeds[target_indices, :]

                                if MEMORY_DEBUG_ENABLED:
                                    print(f"  Target_step: {target_step}")
                                    print(f"  Target_indices shape: {target_indices.shape}, max: {target_indices.max() if target_indices.shape[0] > 0 else 'N/A'}")
                                    print(f"  Normalized_embeds shape: {normalized_embeds.shape}")

                                # Memory debug: Before similarity computation
                                if MEMORY_DEBUG_ENABLED:
                                    log_memory_stats("VisionZip: Before similarity computation", verbose=True)

                                # Compute similarity for source tokens to targets
                                source_mask = ~torch.isin(torch.arange(normalized_embeds.shape[0], device=device), target_indices)
                                source_embeds = normalized_embeds[source_mask]

                                if MEMORY_DEBUG_ENABLED:
                                    print(f"  Source embeds shape: {source_embeds.shape}")
                                    print(f"  Target embeds shape: {target_embeds.shape}")
                                    print(f"  Expected similarity matrix: {source_embeds.shape[0]} x {target_embeds.shape[0]}")
                                    similarity_memory_gb = (source_embeds.shape[0] * target_embeds.shape[0] * 4) / 1024**3
                                    print(f"  Estimated similarity matrix memory: {similarity_memory_gb:.3f} GB")

                                if source_embeds.shape[0] > 0 and target_embeds.shape[0] > 0:
                                    try:
                                        similarity = torch.matmul(source_embeds, target_embeds.t())

                                        # Memory debug: After similarity computation
                                        if MEMORY_DEBUG_ENABLED:
                                            log_memory_stats("VisionZip: After similarity computation", verbose=True)
                                            log_tensor_info(similarity, "Similarity matrix")

                                    except torch.cuda.OutOfMemoryError as e:
                                        if MEMORY_DEBUG_ENABLED:
                                            print(f"\n{'!'*70}")
                                            print(f"!!! OOM at similarity matrix computation !!!")
                                            print(f"{'!'*70}")
                                            print(f"  Tried to compute: {source_embeds.shape} @ {target_embeds.shape}.T")
                                            log_memory_stats("OOM at similarity", show_tensors=True, verbose=True)
                                        raise e

                                    assign_one_hot = image_embeds.new_zeros(source_embeds.shape[0], contextual_token_num)
                                    assign_one_hot.scatter_(1, similarity.argmax(dim=-1).unsqueeze(-1), 1)
                                    counts = assign_one_hot.sum(dim=0).clamp(min=1).unsqueeze(-1)

                                    # Memory debug: Before aggregation
                                    if MEMORY_DEBUG_ENABLED:
                                        log_memory_stats("VisionZip: Before aggregation", verbose=True)

                                    # Get actual indices in the original image_embeds space
                                    contextual_positions = (~selected_masks).nonzero(as_tuple=True)[0]

                                    if MEMORY_DEBUG_ENABLED:
                                        print(f"  Contextual_positions shape: {contextual_positions.shape}")
                                        print(f"  Target_indices max: {target_indices.max() if target_indices.shape[0] > 0 else 'N/A'}")
                                        print(f"  Source_mask sum: {source_mask.sum()}")

                                    target_positions = contextual_positions[target_indices]
                                    source_positions = contextual_positions[source_mask]

                                    # Mark target tokens as selected
                                    selected_masks[target_positions] = True

                                    try:
                                        # Aggregate source embeddings into targets (use normalized embeddings)
                                        # This matches InternVL3 implementation (line 537)
                                        aggregated_embeds = torch.matmul(assign_one_hot.t(), source_embeds) / counts

                                        # Memory debug: After aggregation
                                        if MEMORY_DEBUG_ENABLED:
                                            log_memory_stats("VisionZip: After aggregation", verbose=True)
                                            print(f"  Aggregated embeds shape: {aggregated_embeds.shape}")

                                    except torch.cuda.OutOfMemoryError as e:
                                        if MEMORY_DEBUG_ENABLED:
                                            print(f"\n{'!'*70}")
                                            print(f"!!! OOM at embedding aggregation !!!")
                                            print(f"{'!'*70}")
                                            log_memory_stats("OOM at aggregation", show_tensors=True, verbose=True)
                                        raise e

                                    image_embeds[target_positions] += aggregated_embeds

                    # Memory debug: VisionZip complete
                    if MEMORY_DEBUG_ENABLED:
                        log_memory_stats("VisionZip: Complete", verbose=True)
                elif self.pruning_method == 'holov':
                    # HoloV (NeurIPS 2025, arXiv 2510.02912), single-stage vision-side.
                    # Official `llava/model/utils.py:HoloV` splits an image's tokens into
                    # sequential patches, allocates a keep-budget across patches by
                    # (CLS-attn + similarity-variance), then keeps the top-CLS-attn tokens
                    # inside each patch. Selection only -- no merging.
                    #
                    # Qwen2.5-VL adaptation: `image_embeds` is a flat [N, D] tensor holding
                    # possibly several images, so we split it by `image_grid_thw` and run
                    # the allocation per image (the official code's B/num_patches loop).
                    # The patch grid is the near-square factorisation of `num_patches`,
                    # matching InternVL3's `holov` branch so both models share one recipe.
                    if image_attns is None:
                        raise ValueError("HoloV requires attention weights, but they are not available")
                    # [heads, N, N] -> per-token relevance; mean over query rows and heads,
                    # the same reduction the TOPS/tops_variant3 selector consumes.
                    if image_attns.dim() == 3:
                        holov_relevance = image_attns.mean(dim=0).mean(dim=0)   # [N]
                    elif image_attns.dim() == 2:
                        holov_relevance = image_attns.mean(dim=0)               # [N]
                    else:
                        holov_relevance = image_attns                          # [N]

                    alpha, beta, power, eps = 1.0, 0.09, 1.0, 1e-6
                    # Per-image token lattice: grid_thw is (t, H, W) in patch units and
                    # the 2x2 patch merger gives an H/2 x W/2 embedding grid per frame,
                    # so the region grid uses the image's true spatial shape.
                    img_shapes = []
                    for thw in image_grid_thw:
                        t_i, h_i, w_i = int(thw[0].item()), int(thw[1].item()), int(thw[2].item())
                        img_shapes.append((t_i, h_i // 2, w_i // 2))

                    from vlmeval.vlm.holov_select import holov_select
                    selected_masks = holov_select(
                        image_embeds, holov_relevance, img_shapes, self.target_visual_token_num,
                        alpha=alpha, beta=beta, power=power, eps=eps,
                    )
                    print(f"[HoloV] {len(img_shapes)} image(s), tokens "
                          f"{[f * h * w for (f, h, w) in img_shapes]} -> kept "
                          f"{int(selected_masks.sum().item())} (target {self.target_visual_token_num})")
                elif self.pruning_method == 'vispruner':
                    important_token_num = int(self.target_visual_token_num * 0.9)
                    diverse_token_num = self.target_visual_token_num - important_token_num

                    # image_attns is already per-key relevance [N] (heads/queries reduced
                    # during capture); keep a defensive squeeze for any [h, N, N] fallback.
                    if image_attns.dim() == 3:
                        image_attns = image_attns.mean(dim=1).mean(dim=0)
                    elif image_attns.dim() == 2:
                        image_attns = image_attns.mean(dim=0)
                    else:
                        image_attns = image_attns.reshape(-1)
                    if image_attns.shape[0] != N:
                        raise ValueError(f"vispruner relevance length {image_attns.shape[0]} != tokens {N}")
                    token_indices = image_attns.argsort(dim=-1, descending=True)

                    important_indices = token_indices[:important_token_num]
                    residual_indices = token_indices[important_token_num:]

                    image_normalized = image_embeds / image_embeds.norm(dim=-1, keepdim=True)
                    while diverse_token_num > 0:
                        residual_embeds = image_normalized[residual_indices]
                        r = min(8, residual_embeds.shape[0] - diverse_token_num)
                        if r <= 0:
                            break

                        a, b = residual_embeds[::2], residual_embeds[1::2]
                        scores = a @ b.t()
                        scores = scores.max(dim=-1).values

                        distinct_indices = scores.argsort(dim=-1, descending=True)[r:]
                        residual_indices = torch.cat([residual_indices[::2][distinct_indices], residual_indices[1::2]])

                    selected_indices = torch.cat([important_indices, residual_indices])
                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[selected_indices] = True
                    if int(selected_masks.sum()) != min(self.target_visual_token_num, N):
                        raise ValueError("VisPruner did not meet the requested visual token budget")
                    print(f"[VisPruner Qwen2.5] tokens {N} -> {int(selected_masks.sum())} "
                          f"(target {self.target_visual_token_num}, important_ratio=0.9)")
                elif self.pruning_method == 'divprune':
                    # DivPrune: Diversity-based greedy token selection
                    # Reference: InternVL3 implementation (modeling_internvl_chat.py:539-564)
                    # Adapted for Qwen2.5-VL's flat [N, D] format (no batch dimension)

                    image_normalized = image_embeds / image_embeds.norm(dim=-1, keepdim=True)
                    cosine_matrix = 1.0 - torch.matmul(image_normalized, image_normalized.t())  # [N, N]

                    selected_indices = torch.empty(self.target_visual_token_num, dtype=torch.long, device=device)

                    for i in range(self.target_visual_token_num):
                        if i == 0:
                            # Initial selection: token with maximum diversity (2nd smallest cosine distance)
                            # This finds the token that is most different from all others
                            m2 = cosine_matrix  # [N, N]
                            scores = torch.topk(m2, 2, dim=0, largest=False).values[1]  # [N]
                        else:
                            # Subsequent selections: maximize minimum distance to already selected tokens
                            # Select rows corresponding to already selected tokens
                            m2 = cosine_matrix[selected_indices[:i], :]  # [i, N]
                            scores = torch.min(m2, dim=0).values  # [N]

                            # Mask out already selected indices to prevent re-selection
                            scores[selected_indices[:i]] = -float('inf')

                        # Select token with highest diversity score
                        selected_idx = torch.argmax(scores)
                        selected_indices[i] = selected_idx

                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[selected_indices] = True
                elif self.pruning_method == 'divprune_coverage':
                    # DivPrune-Coverage: DivPrune 的贪心框架, 但把选择准则从
                    # "max-min diversity(到已选集的最小距离最大)" 换成
                    # "SCOPE coverage 边际增益" (取自 TOPS): 每步选能最多覆盖
                    # 尚未被覆盖 token 的那个。coverage(i)=Σ_k max(0, sim(i,k)-g_k),
                    # g_k = max_{j∈S} sim(j,k) (已选集对 token k 的最佳覆盖度)。
                    # 无 relevance、无加权, 纯 coverage 贪心, 与 DivPrune 严格对照。
                    image_normalized = image_embeds / (image_embeds.norm(dim=-1, keepdim=True) + 1e-8)
                    sim = torch.matmul(image_normalized, image_normalized.t())      # [N,N] 余弦相似度
                    K = self.target_visual_token_num
                    device_ = image_embeds.device
                    avail = torch.ones(N, dtype=torch.bool, device=device_)
                    selected = []
                    # g_k: 已选集对每个 token 的最佳覆盖度, 初始为 0 (空集谁都没覆盖)
                    g = torch.zeros(N, device=device_)
                    # step 0: 选覆盖全集增益最大的 (g=0 时 coverage(i)=Σ_k max(0,sim(i,k))=Σ sim⁺)
                    cov0 = torch.clamp(sim, min=0.0).sum(dim=1)
                    i0 = int(torch.argmax(cov0).item())
                    selected.append(i0); avail[i0] = False
                    g = torch.maximum(g, sim[i0])
                    for _ in range(1, K):
                        if not avail.any():
                            break
                        # 边际覆盖增益: 每个候选 i 加入后能新增多少覆盖
                        gain = torch.clamp(sim - g.unsqueeze(0), min=0.0).sum(dim=1)  # [N]
                        gain[~avail] = -float('inf')
                        j = int(torch.argmax(gain).item())
                        selected.append(j); avail[j] = False
                        g = torch.maximum(g, sim[j])
                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[torch.tensor(selected, device=device, dtype=torch.long)] = True
                    print(f"[divprune_coverage] K={K} selected={int(selected_masks.sum().item())}")
                elif self.pruning_method == 'divprune_coverage_to_others_only':
                    # 消融: coverage = 自覆盖(diversity, k=i项) + 交叉覆盖(k≠i项)。
                    # 本变体只用「交叉覆盖」——排除对角线 k=i 自项, 纯粹衡量"覆盖别人"的贡献。
                    # gain(i)=Σ_{k≠i} max(0, sim(i,k)-g_k), 其余与 divprune_coverage 完全一致。
                    image_normalized = image_embeds / (image_embeds.norm(dim=-1, keepdim=True) + 1e-8)
                    sim = torch.matmul(image_normalized, image_normalized.t())      # [N,N]
                    sim_off = sim.clone()
                    sim_off.fill_diagonal_(0.0)                                     # 去掉自项 k=i
                    K = self.target_visual_token_num
                    device_ = image_embeds.device
                    avail = torch.ones(N, dtype=torch.bool, device=device_)
                    selected = []
                    g = torch.zeros(N, device=device_)
                    # step 0: 用交叉覆盖 (g=0, 自项已去) 选覆盖别人最多的
                    cov0 = torch.clamp(sim_off, min=0.0).sum(dim=1)
                    i0 = int(torch.argmax(cov0).item())
                    selected.append(i0); avail[i0] = False
                    g = torch.maximum(g, sim[i0])   # g 仍用完整 sim 更新(覆盖度含对所有token)
                    for _ in range(1, K):
                        if not avail.any():
                            break
                        # 只算对「其他」token 的边际覆盖增益 (自项 sim_off 对角=0 已排除)
                        gain = torch.clamp(sim_off - g.unsqueeze(0), min=0.0).sum(dim=1)  # [N]
                        gain[~avail] = -float('inf')
                        j = int(torch.argmax(gain).item())
                        selected.append(j); avail[j] = False
                        g = torch.maximum(g, sim[j])
                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[torch.tensor(selected, device=device, dtype=torch.long)] = True
                    print(f"[divprune_coverage_to_others_only] K={K} selected={int(selected_masks.sum().item())}")
                elif self.pruning_method in ('cover_qe', 'cover_prune', 'cover_e', 'cover_q', 'cover_u'):
                    # COVER-Prune (加权 facility-location coverage). 主方法 cover_qe:
                    #   w_v = energy_v * task_v,  energy_v=||x_v||²(归一), task_v=(1-λ)+λ·N·softmax(r_v/τ)
                    #   r_v(Q)=max_t cos(视觉v, 文本query token t)  (LLM hidden space)
                    #   目标 max_S Σ_v w_v·max_{s∈S} κ(v,s), κ=max(0,cos), 次模贪心 (1-1/e) 保证
                    # 消融: cover_u(w=1)/cover_e(仅energy)/cover_q(仅task)/cover_qe(energy×task)
                    import os as _os
                    lam = float(_os.environ.get('COVER_LAMBDA', '0.5'))
                    tau = float(_os.environ.get('COVER_TAU', '0.1'))
                    use_e = self.pruning_method in ('cover_qe', 'cover_prune', 'cover_e')
                    use_q = self.pruning_method in ('cover_qe', 'cover_prune', 'cover_q')
                    device_ = image_embeds.device
                    K = self.target_visual_token_num
                    # κ: 非负余弦相似度 [N,N]
                    image_normalized = image_embeds / (image_embeds.norm(dim=-1, keepdim=True) + 1e-8)
                    sim = torch.clamp(torch.matmul(image_normalized, image_normalized.t()), min=0.0)
                    # ── energy 权重 e_v = ||x_v||² (归一化到均值1) ──
                    if use_e:
                        energy = image_embeds.float().pow(2).sum(dim=-1)             # [N]
                        energy = energy / (energy.mean() + 1e-6)
                    else:
                        energy = torch.ones(N, device=device_)
                    # ── task 权重 a_v(Q) = (1-λ)+λ·N·softmax(r_v/τ) ──
                    if use_q:
                        img_idx = torch.where(input_ids == self.config.image_token_id)[1]
                        te = inputs_embeds.squeeze(0)[img_idx[-1] + 2:-5].float()     # 文本query token (M,D)
                        if te.shape[0] > 0:
                            ie = image_embeds.float()
                            ien = ie / (ie.norm(dim=-1, keepdim=True) + 1e-8)
                            ten = te / (te.norm(dim=-1, keepdim=True) + 1e-8)
                            r_v = torch.matmul(ien, ten.t()).max(dim=1).values        # [N] max over query tokens
                            pi = torch.softmax(r_v / tau, dim=0)
                            task = (1.0 - lam) + lam * N * pi
                        else:
                            task = torch.ones(N, device=device_)
                    else:
                        task = torch.ones(N, device=device_)
                    w = (energy * task).to(sim.dtype)                                # [N] 覆盖权重
                    w = w / (w.mean() + 1e-6)
                    # ── 加权 facility-location 贪心 ──
                    avail = torch.ones(N, dtype=torch.bool, device=device_)
                    selected = []
                    g = torch.zeros(N, device=device_, dtype=sim.dtype)
                    cov0 = (w.unsqueeze(0) * sim).sum(dim=1)                          # Σ_v w_v·κ(v,i)
                    i0 = int(torch.argmax(cov0).item())
                    selected.append(i0); avail[i0] = False
                    g = torch.maximum(g, sim[i0])
                    for _ in range(1, K):
                        if not avail.any():
                            break
                        gain = (w.unsqueeze(0) * torch.clamp(sim - g.unsqueeze(0), min=0.0)).sum(dim=1)  # Σ_v w_v·[κ-g]⁺
                        gain[~avail] = -float('inf')
                        j = int(torch.argmax(gain).item())
                        selected.append(j); avail[j] = False
                        g = torch.maximum(g, sim[j])
                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[torch.tensor(selected, device=device, dtype=torch.long)] = True
                    print(f"[{self.pruning_method}] K={K} λ={lam} τ={tau} e={use_e} q={use_q} selected={int(selected_masks.sum().item())}")
                elif self.pruning_method in ('mmtok', 'mmtok_origin'):
                    # MMTok (arXiv 2508.18264, 竞品): 多模态最大覆盖. 单阶段, projector 后.
                    #   P = softmax(z_norm@x_norm.T / tv)/M  文本→视觉覆盖 [M,N]
                    #   Q = softmax(x_norm@x_norm.T / vv)/N  视觉→视觉覆盖(多样) [N,N]
                    #   Combined=[P; α·Q], 贪心最大覆盖 delta_j=Σ_row max(0,Combined[row,j]-best[row])
                    # mmtok: 文本取 prompt 内已嵌入的 text token (近似); mmtok_origin: 完全对齐官方,
                    #   重新编码 "Question: {question}" (split-into-words, 去BOS). Q 均用 ViT 空间.
                    import os as _os
                    tv = float(_os.environ.get('MMTOK_TV_TEMP', '0.01'))
                    vv = float(_os.environ.get('MMTOK_VV_TEMP', '0.2'))
                    alpha = float(_os.environ.get('MMTOK_ALPHA', '0.5'))
                    device_ = image_embeds.device
                    K = min(self.target_visual_token_num, N)
                    x = image_embeds.float()
                    x_norm = x / (x.norm(dim=-1, keepdim=True) + 1e-8)
                    # 文本 query token
                    if self.pruning_method == 'mmtok_origin':
                        # 官方对齐: 重新编码 "Question: {question}" (is_split_into_words=True, 去BOS), 过 embed_tokens
                        te = x.new_zeros((0, x.shape[1]))
                        q_text = getattr(self, '_mmtok_question', None)
                        tok = getattr(self, '_mmtok_tokenizer', None)
                        if q_text and tok is not None:
                            enc = tok(("Question: " + q_text).split(), is_split_into_words=True,
                                      return_tensors="pt", padding=True, truncation=True)
                            qids = enc["input_ids"].to(device_)
                            emb = self.get_input_embeddings()(qids)[0]                        # [T,D]
                            st = 1 if (qids.shape[1] > 1 and tok.bos_token_id is not None and int(qids[0, 0]) == tok.bos_token_id) else 0
                            te = emb[st:].float()
                    else:
                        img_idx = torch.where(input_ids == self.config.image_token_id)[1]
                        te = inputs_embeds.squeeze(0)[img_idx[-1] + 2:-5].float() if img_idx.numel() > 0 else x.new_zeros((0, x.shape[1]))
                    # Q 用 ViT 合并前特征 (MMTok 原文): reshape(seq//4,4,-1).mean(1)[reverse_indices] → [N,1280]
                    vit_feat = getattr(self, '_mmtok_merger_in', None)
                    if vit_feat is not None and vit_feat.shape[0] // 4 == N:
                        _wi, _ = self.visual.get_window_index(image_grid_thw)
                        _rev = torch.argsort(_wi)
                        q_feat = vit_feat.float().reshape(vit_feat.shape[0] // 4, 4, -1).mean(dim=1)[_rev, :]  # [N,1280]
                        q_src = 'vit'
                    else:
                        q_feat = x                                                        # fallback: projector 输出
                        q_src = 'proj'
                    qn = q_feat / (q_feat.norm(dim=-1, keepdim=True) + 1e-8)
                    Q = torch.softmax((qn @ qn.t()) / vv, dim=1) / N                      # [N,N] 视觉→视觉(ViT空间)
                    if te.shape[0] > 0:
                        z_norm = te / (te.norm(dim=-1, keepdim=True) + 1e-8)
                        M = z_norm.shape[0]
                        P = torch.softmax((z_norm @ x_norm.t()) / tv, dim=1) / M          # [M,N]
                        Combined = torch.cat([P, alpha * Q], dim=0)                        # [M+N, N]
                    else:
                        Combined = alpha * Q                                               # 无文本时退化为纯视觉覆盖
                    # 贪心最大覆盖
                    best = torch.zeros(Combined.shape[0], device=device_, dtype=Combined.dtype)
                    score_mask = torch.zeros(N, device=device_, dtype=Combined.dtype)
                    sel = torch.empty(K, dtype=torch.long, device=device_)
                    for i in range(K):
                        delta = (Combined - best.unsqueeze(1)).clamp_min(0.0).sum(dim=0)   # [N]
                        delta = delta + score_mask
                        j = int(torch.argmax(delta).item())
                        sel[i] = j
                        best = torch.maximum(best, Combined[:, j])
                        score_mask[j] = -float('inf')
                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[sel] = True
                    print(f"[{self.pruning_method}] K={K} tv={tv} vv={vv} alpha={alpha} Q_space={q_src} M_text={te.shape[0]} selected={int(selected_masks.sum().item())}")
                elif self.pruning_method == 'dppruner':
                    image_normalized = image_embeds / image_embeds.norm(dim=-1, keepdim=True)
                    similarity = torch.matmul(image_normalized, image_normalized.t())

                    kernel = similarity

                    cis = kernel.new_zeros((self.target_visual_token_num, N))
                    di2s = torch.diag(kernel)
                    selected_indices = torch.empty(self.target_visual_token_num, dtype=torch.long, device=device)
                    for i in range(self.target_visual_token_num):
                        j = torch.argmin(torch.max(similarity, dim=-1).values) if i==0 else torch.argmax(di2s)
                        # j = torch.argmax(di2s)
                        selected_indices[i] = j

                        eis = (kernel[j, :] - cis[:i, j] @ cis[:i, :]) / torch.sqrt(di2s[j])
                        cis[i, :] = eis
                        di2s -= torch.square(eis)
                        di2s[j] = -float('inf')

                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[selected_indices] = True
                elif self.pruning_method in ('tsvol', 'tsvol_w', 'tsvol_anti', 'tsvol_w_anti'):
                    # TSVOL (Text-Subspace VOLume) 从 LLaVA-TOPS-ICLR 移植到 Qwen2.5-VL。
                    # 在 LLM 输入空间: 对 prompt 文本 embedding 做 SVD 取正交基 Q_T,
                    #   normal: 视觉 token 投影到文本子空间坐标 U=ie@Q_T (选和文本最相关+多样)
                    #   anti  : 取文本子空间正交补残差 U=ie-(ie@Q_T)Q_T^T (选和文本互补+多样)
                    # 再对 U 做 QR max-volume 贪心选 K 个 (选体积最大=最多样的子集),
                    # 不足 K 时按投影范数(relevance) fallback 补齐。_w 变体按 cls_attn^0.5 行加权。
                    import os as _os
                    weighted = self.pruning_method in ('tsvol_w', 'tsvol_w_anti')
                    anti = self.pruning_method in ('tsvol_anti', 'tsvol_w_anti')
                    tol = float(_os.environ.get('TSVOL_TOL', '1e-3'))
                    K = self.target_visual_token_num
                    ie = image_embeds.float()                                  # (N, D)
                    Nv, Cf = ie.shape
                    if _os.environ.get('TSVOL_VNORM', '0') == '1':
                        ie = ie / (ie.norm(dim=-1, keepdim=True) + 1e-8)
                    # 文本 embedding (prompt 文本 token, 去掉图像占位与尾部特殊符, 同 trim_mean 口径)
                    # 在本分支内显式计算，避免 weighted 变体进入 attention
                    # 提取分支后跳过上游 trim/cdpruner gating 而未赋值。
                    image_token_indices = torch.where(
                        input_ids == self.config.image_token_id
                    )[1]
                    te = inputs_embeds.squeeze(0)[image_token_indices[-1] + 2:-5].float()  # (M, D)
                    # 文本子空间正交基 Q_T (D, r), rank 由 tol 定
                    _, s_t, vh_t = torch.linalg.svd(te, full_matrices=False)
                    r = int((s_t > tol * s_t[0]).sum().item()) if s_t.numel() > 0 else 1
                    r = max(r, 1)
                    Q_T = vh_t[:r].transpose(0, 1)                             # (D, r)
                    # CLS 加权
                    w_pow = float(_os.environ.get('TSVOL_W_POW', '0.5' if weighted else '0'))
                    _img_attns = locals().get('image_attns', None)
                    use_w = (w_pow > 0) and (_img_attns is not None)
                    if use_w:
                        if _img_attns.dim() == 3:
                            cls_w = _img_attns.mean(dim=1).mean(dim=0)        # (N,)
                        elif _img_attns.dim() == 2:
                            cls_w = _img_attns.mean(dim=0)
                        else:
                            cls_w = _img_attns
                        w_vec = torch.pow(torch.clamp(cls_w.float(), min=0.0) + 1e-8, w_pow)  # (N,)
                    if anti:
                        coeff = ie @ Q_T                                       # (N, r)
                        U = ie - coeff @ Q_T.transpose(0, 1)                   # (N, D) 残差
                    else:
                        U = ie @ Q_T                                          # (N, r) 投影坐标
                    if use_w:
                        U = U * w_vec.unsqueeze(-1)
                    nrm2 = (U * U).sum(dim=1)                                  # (N,)
                    chosen = []
                    avail = torch.ones(Nv, dtype=torch.bool, device=device)
                    i0 = int(torch.argmax(nrm2).item())
                    chosen.append(i0); avail[i0] = False
                    q0 = U[i0] / (U[i0].norm() + 1e-8)
                    Qbasis = q0.unsqueeze(1)
                    steps = min(K, Nv) if anti else min(K, r, Nv)
                    for _ in range(1, steps):
                        proj = U @ Qbasis
                        resid = U - proj @ Qbasis.transpose(0, 1)
                        res_norm = resid.norm(dim=1)
                        res_norm[~avail] = -float('inf')
                        j = int(torch.argmax(res_norm).item())
                        if res_norm[j].item() <= 1e-6:
                            break
                        chosen.append(j); avail[j] = False
                        qj = resid[j] / (resid[j].norm() + 1e-8)
                        Qbasis = torch.cat([Qbasis, qj.unsqueeze(1)], dim=1)
                    if len(chosen) < K:
                        rem = nrm2.clone(); rem[~avail] = -float('inf')
                        extra = torch.topk(rem, K - len(chosen)).indices
                        chosen.extend(extra.tolist())
                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[torch.tensor(chosen[:K], device=device, dtype=torch.long)] = True
                    print(f"[TSVOL] method={self.pruning_method} K={K} r={r} anti={anti} w={use_w} "
                          f"selected={int(selected_masks.sum().item())}")
                elif self.pruning_method == 'trim_mean':
                    image_normalized = image_embeds / image_embeds.norm(dim=-1, keepdim=True)
                    text_embeds = inputs_embeds.squeeze(0)[image_token_indices[-1]+2:-5]
                    text_normalized = text_embeds / text_embeds.norm(dim=-1, keepdim=True)

                    similarity = torch.matmul(image_normalized, text_normalized.t()).mean(dim=-1)
                    selected_indices = similarity.topk(self.target_visual_token_num, dim=-1).indices

                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[selected_indices] = True
                elif self.pruning_method == 'trim_max':
                    image_normalized = image_embeds / image_embeds.norm(dim=-1, keepdim=True)
                    text_embeds = inputs_embeds.squeeze(0)[image_token_indices[-1]+2:-5]
                    text_normalized = text_embeds / text_embeds.norm(dim=-1, keepdim=True)

                    similarity = torch.matmul(image_normalized, text_normalized.t()).max(dim=-1).values
                    selected_indices = similarity.topk(self.target_visual_token_num, dim=-1).indices

                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[selected_indices] = True
                elif self.pruning_method == 'cdpruner_mean':
                    image_normalized = image_embeds / image_embeds.norm(dim=-1, keepdim=True)
                    similarity = torch.matmul(image_normalized, image_normalized.t())

                    text_embeds = inputs_embeds.squeeze(0)[image_token_indices[-1]+2:-5]
                    text_normalized = text_embeds / text_embeds.norm(dim=-1, keepdim=True)
                    relevance = torch.matmul(image_normalized, text_normalized.t()).mean(dim=-1)
                    relevance = (relevance - relevance.min() + 0.01) / (relevance.max() - relevance.min())

                    kernel = relevance.unsqueeze(1) * similarity * relevance.unsqueeze(0)

                    cis = kernel.new_zeros((self.target_visual_token_num, N))
                    di2s = torch.diag(kernel)
                    selected_indices = torch.empty(self.target_visual_token_num, dtype=torch.long, device=device)
                    for i in range(self.target_visual_token_num):
                        j = torch.argmin(torch.max(similarity, dim=-1).values) if i==0 else torch.argmax(di2s)
                        selected_indices[i] = j

                        eis = (kernel[j, :] - cis[:i, j] @ cis[:i, :]) / torch.sqrt(di2s[j])
                        cis[i, :] = eis
                        di2s -= torch.square(eis)
                        di2s[j] = -float('inf')

                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[selected_indices] = True
                elif self.pruning_method == 'cdpruner_max':
                    image_normalized = image_embeds / image_embeds.norm(dim=-1, keepdim=True)
                    similarity = torch.matmul(image_normalized, image_normalized.t())

                    text_embeds = inputs_embeds.squeeze(0)[image_token_indices[-1]+2:-5]
                    text_normalized = text_embeds / text_embeds.norm(dim=-1, keepdim=True)
                    relevance = torch.matmul(image_normalized, text_normalized.t()).max(dim=-1).values
                    relevance = (relevance - relevance.min() + 0.01) / (relevance.max() - relevance.min())

                    kernel = relevance.unsqueeze(1) * similarity * relevance.unsqueeze(0)

                    cis = kernel.new_zeros((self.target_visual_token_num, N))
                    di2s = torch.diag(kernel)
                    selected_indices = torch.empty(self.target_visual_token_num, dtype=torch.long, device=device)
                    for i in range(self.target_visual_token_num):
                        j = torch.argmin(torch.max(similarity, dim=-1).values) if i==0 else torch.argmax(di2s)
                        selected_indices[i] = j

                        eis = (kernel[j, :] - cis[:i, j] @ cis[:i, :]) / torch.sqrt(di2s[j])
                        cis[i, :] = eis
                    di2s -= torch.square(eis)
                    di2s[j] = -float('inf')

                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[selected_indices] = True
                elif self.pruning_method == 'sparsevlm':
                    selected_masks = torch.ones(N, dtype=torch.bool, device=device)
                elif self.pruning_method == 'tops_variant3':
                    # TOPS-Variant3: Adaptive Two-Stage Text-Concept Hierarchical Pruning
                    print(f"\n{'='*80}")
                    print(f"TOPS-Variant3 Stage 1: THCP (Text-Concept Hierarchical Pruning)")
                    print(f"{'='*80}")

                    # Extract text embeddings from inputs_embeds
                    image_token_indices = (input_ids == self.config.image_token_id).nonzero(as_tuple=True)[1]
                    if len(image_token_indices) > 0:
                        image_token_end = image_token_indices[-1].item()
                        # Extract text tokens after image tokens (exclude last 5 tokens for padding/eos)
                        text_start_idx = image_token_end + 1
                        text_end_idx = input_ids.shape[1] - 5

                        if text_start_idx < text_end_idx:
                            text_embeds = inputs_embeds.squeeze(0)[text_start_idx:text_end_idx]
                        else:
                            text_embeds = torch.tensor([], device=device)
                    else:
                        text_embeds = torch.tensor([], device=device)

                    M = text_embeds.shape[0]

                    # Fallback to attention-based if no text
                    if M == 0:
                        print("[TOPS-Variant3 Warning] No text embeddings found, using attention fallback")
                        image_attns = image_attns.mean(dim=1).mean(dim=0)
                        selected_indices = image_attns.topk(self.target_visual_token_num, dim=-1).indices
                        selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                        selected_masks[selected_indices] = True
                    else:
                        # Adaptive Stage 1: keep target × 2 tokens (relevance-only)
                        stage1_keep_num = max(1, self.target_visual_token_num * 2)
                        tokens_to_select = min(stage1_keep_num, N)

                        print(f"  Visual tokens: {N}")
                        print(f"  Text tokens: {M}")
                        print(f"  Target (final): {self.target_visual_token_num}")
                        print(f"  Stage 1 target: {tokens_to_select} (adaptive: target × 2)")
                        print(f"  Mode: Relevance")

                        # Normalize embeddings
                        image_normalized = image_embeds / (image_embeds.norm(dim=-1, keepdim=True) + 1e-8)
                        text_normalized = text_embeds / (text_embeds.norm(dim=-1, keepdim=True) + 1e-8)

                        # Relevance scores averaged across text tokens when M > 1
                        response_matrix = torch.matmul(image_normalized, text_normalized.t())  # (N, M)
                        if M > 1:
                            text_relevance = response_matrix.mean(dim=-1)
                        else:
                            text_relevance = response_matrix.squeeze(-1)

                        text_relevance = (text_relevance - text_relevance.min()) / (
                            (text_relevance.max() - text_relevance.min()) + 1e-6
                        )

                        visual_similarity = torch.matmul(image_normalized, image_normalized.t())
                        available_mask = torch.ones(N, dtype=torch.bool, device=device)
                        selected_indices: List[int] = []

                        relevance_weight = 0.5
                        diversity_weight = 0.5

                        for step in range(tokens_to_select):
                            if not available_mask.any():
                                break

                            scores = text_relevance.clone()
                            if step > 0:
                                selected_tensor = torch.tensor(selected_indices, device=device, dtype=torch.long)
                                max_similarity_to_selected = visual_similarity[:, selected_tensor].max(dim=1).values
                                diversity_scores = 1 - max_similarity_to_selected
                                scores = relevance_weight * scores + diversity_weight * diversity_scores

                            scores[~available_mask] = -float('inf')
                            selected_idx = scores.argmax().item()
                            selected_indices.append(selected_idx)
                            available_mask[selected_idx] = False

                        if len(selected_indices) == 0:
                            selected_indices = list(range(tokens_to_select))

                        selected_tensor = torch.tensor(selected_indices, device=device, dtype=torch.long)
                        selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                        selected_masks[selected_tensor] = True

                        print(f"[TOPS-Variant3 Stage1] selected_masks.sum = {selected_masks.sum().item()}")

                        print(f"  Selected {selected_masks.sum().item()} visual tokens")
                        print(f"{'='*80}\n")


                elif self.pruning_method in ('cover_prune_1', 'cover_prune_1_proj', 'scope_vit_origin', 'scope_vit_origin_raw'):
                    # cover_prune_1: 双阶段S1(→target×2); cover_prune_1_proj: 单阶段=SCOPE(embed空间, →target)
                    # scope_vit_origin: SCOPE 外加权, coverage 在 ViT 空间, cls_attn 归一化[0,1](单阶段)
                    # scope_vit_origin_raw: 同上但 cls_attn 不归一化(真SCOPE: raw attn**alpha, alpha=1)
                    # after-projector: cls_attn × coverage 直接相乘
                    import os
                    _raw = self.pruning_method.endswith('_raw')
                    _single = self.pruning_method.endswith('_proj') or self.pruning_method in ('scope_vit_origin', 'scope_vit_origin_raw')
                    stage1_keep_num = min(max(1, self.target_visual_token_num * (1 if _single else 2)), N)
                    # cls_attn (视觉encoder attention, 同tops)
                    if image_attns is not None:
                        if image_attns.dim() == 3:
                            cls_attn = image_attns.mean(dim=1).mean(dim=0)
                        elif image_attns.dim() == 2:
                            cls_attn = image_attns.mean(dim=0)
                        else:
                            cls_attn = image_attns
                    else:
                        cls_attn = image_embeds.norm(dim=-1)
                    if not _raw:
                        cls_attn = (cls_attn - cls_attn.min()) / (cls_attn.max() - cls_attn.min() + 1e-8)  # [0,1]归一化
                    # else: 原始 cls_attn (真SCOPE, 不归一化)
                    # coverage 相似度空间: 默认 embed(projector输出); scope_vit_origin(_raw) 用 ViT 合并前特征
                    if self.pruning_method in ('scope_vit_origin', 'scope_vit_origin_raw'):
                        vit_feat = getattr(self, '_mmtok_merger_in', None)
                        if vit_feat is not None and vit_feat.shape[0] // 4 == N:
                            _wi, _ = self.visual.get_window_index(image_grid_thw)
                            _rev = torch.argsort(_wi)
                            cov_feat = vit_feat.float().reshape(vit_feat.shape[0] // 4, 4, -1).mean(dim=1)[_rev, :]
                            _covsrc = 'vit'
                        else:
                            cov_feat = image_embeds.float(); _covsrc = 'proj(fallback)'
                    else:
                        cov_feat = image_embeds.float(); _covsrc = 'proj'
                    image_normalized = cov_feat / (cov_feat.norm(dim=-1, keepdim=True) + 1e-8)
                    sim = torch.matmul(image_normalized, image_normalized.t())
                    avail = torch.ones(N, dtype=torch.bool, device=device)
                    selected = []
                    g = torch.zeros(N, device=device)
                    # seed: cls_attn × coverage(空集时 coverage=Σ sim⁺)
                    cov0 = torch.clamp(sim, min=0.0).sum(dim=1)
                    i0 = int(torch.argmax(cls_attn * cov0).item())
                    selected.append(i0); avail[i0] = False; g = torch.maximum(g, sim[i0])
                    for _ in range(1, stage1_keep_num):
                        if not avail.any(): break
                        coverage = torch.clamp(sim - g.unsqueeze(0), min=0.0).sum(dim=1)  # SCOPE边际增益
                        scores = cls_attn * coverage                                       # 直接相乘(外加权)
                        scores[~avail] = -float('inf')
                        j = int(torch.argmax(scores).item())
                        selected.append(j); avail[j] = False; g = torch.maximum(g, sim[j])
                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[torch.tensor(selected, device=device, dtype=torch.long)] = True
                    print(f"[COVER_Prune_1 S1] cls_attn×coverage cov_space={_covsrc}: N={N} → keep {int(selected_masks.sum().item())} (keep={stage1_keep_num})")
                elif self.pruning_method in ('cover_prune_2', 'cover_prune_2_proj', 'cover_prune_2_projector_vit', 'cover_prune_2_proj_raw', 'cover_prune_2_projector_vit_raw', 'cover_prune_2_projector_vit_raw_merge_first', 'cover_prune_2_projector_merge_first'):
                    # cover_prune_2: 双阶段S1(→target×2); cover_prune_2_proj: 单阶段embed(→target)
                    # cover_prune_2_projector_vit: 单阶段, coverage 在 ViT 空间; *_raw: cls_attn 不归一化
                    # *_merge_first: 先对 cov_feat 做 bipartite aff² 近重复预合并(同tops+), 再内加权coverage选
                    #   cover_prune_2_projector_vit_raw_merge_first: ViT空间 + raw attn + merge
                    #   cover_prune_2_projector_merge_first:        embed空间 + 归一化attn + merge
                    # after-projector: cls_attn 乘进coverage每一项 (w_v=被覆盖token cls_attn)
                    # gain(i) = Σ_v cls_attn(v) · max(0, sim(v,i) - g_v)
                    import os
                    _raw = '_raw' in self.pruning_method
                    _mergefirst = 'merge_first' in self.pruning_method
                    _vitspace = 'projector_vit' in self.pruning_method
                    _single = self.pruning_method != 'cover_prune_2'  # 除双阶段cp2外均单阶段(→target)
                    stage1_keep_num = min(max(1, self.target_visual_token_num * (1 if _single else 2)), N)
                    if image_attns is not None:
                        if image_attns.dim() == 3:
                            cls_attn = image_attns.mean(dim=1).mean(dim=0)
                        elif image_attns.dim() == 2:
                            cls_attn = image_attns.mean(dim=0)
                        else:
                            cls_attn = image_attns
                    else:
                        cls_attn = image_embeds.norm(dim=-1)
                    if not _raw:
                        cls_attn = (cls_attn - cls_attn.min()) / (cls_attn.max() - cls_attn.min() + 1e-8)  # [0,1]归一化
                    # else: 原始 cls_attn (不归一化)
                    # coverage 相似度空间: 默认 projector 输出; *_vit 用 ViT 合并前特征 (mean-pool+reverse)
                    if _vitspace:
                        vit_feat = getattr(self, '_mmtok_merger_in', None)
                        if vit_feat is not None and vit_feat.shape[0] // 4 == N:
                            _wi, _ = self.visual.get_window_index(image_grid_thw)
                            _rev = torch.argsort(_wi)
                            cov_feat = vit_feat.float().reshape(vit_feat.shape[0] // 4, 4, -1).mean(dim=1)[_rev, :]
                            _covsrc = 'vit'
                        else:
                            cov_feat = image_embeds.float(); _covsrc = 'proj(fallback)'
                    else:
                        cov_feat = image_embeds.float(); _covsrc = 'proj'
                    # ── merge-first: 对 coverage 用的 cov_feat 做 bipartite aff² 近重复预合并(同tops+, 不减token数) ──
                    if _mergefirst:
                        import math as _math
                        tgt = max(1, self.target_visual_token_num)
                        R = max(1, int(round(_math.log2(max(2.0, N / max(1.0, float(tgt)))))))
                        cov_feat = cov_feat.clone()
                        for _r in range(R):
                            fn = cov_feat / (cov_feat.norm(dim=-1, keepdim=True) + 1e-8)
                            simfull = torch.matmul(fn, fn.t())
                            idxA = torch.arange(0, N, 2, device=device)
                            idxB = torch.arange(1, N, 2, device=device)
                            if idxA.numel() == 0 or idxB.numel() == 0:
                                break
                            simAB = simfull[idxA][:, idxB]
                            bestB = simAB.argmax(dim=1)
                            aff = simAB.max(dim=1).values.clamp(min=0.0)
                            w = aff * aff
                            newB = cov_feat[idxB].clone()
                            wsumB = torch.ones(idxB.shape[0], device=device)
                            newB.index_add_(0, bestB, w.unsqueeze(-1) * cov_feat[idxA])
                            wsumB.index_add_(0, bestB, w)
                            newB = newB / wsumB.unsqueeze(-1).clamp(min=1e-6)
                            cov_feat[idxB] = newB
                            cov_feat[idxA] = newB[bestB]
                        print(f"[cp2projvit_raw_merge_first] {R}-round pre-merge on cov_feat(vit): N={N} target={tgt}")
                    image_normalized = cov_feat / (cov_feat.norm(dim=-1, keepdim=True) + 1e-8)
                    sim = torch.clamp(torch.matmul(image_normalized, image_normalized.t()), min=0.0)
                    avail = torch.ones(N, dtype=torch.bool, device=device)
                    selected = []
                    g = torch.zeros(N, device=device)
                    # seed: 加权覆盖最大 Σ_v cls_attn(v)·sim(v,i)
                    cov0 = (cls_attn.unsqueeze(0) * sim).sum(dim=1)
                    i0 = int(torch.argmax(cov0).item())
                    selected.append(i0); avail[i0] = False; g = torch.maximum(g, sim[i0])
                    for _ in range(1, stage1_keep_num):
                        if not avail.any(): break
                        gain = (cls_attn.unsqueeze(0) * torch.clamp(sim - g.unsqueeze(0), min=0.0)).sum(dim=1)
                        gain[~avail] = -float('inf')
                        j = int(torch.argmax(gain).item())
                        selected.append(j); avail[j] = False; g = torch.maximum(g, sim[j])
                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[torch.tensor(selected, device=device, dtype=torch.long)] = True
                    print(f"[COVER_Prune_2 S1] Σ cls_attn(v)·cov cov_space={_covsrc}: N={N} → keep {int(selected_masks.sum().item())} (keep={stage1_keep_num})")
                elif self.pruning_method in ('mico_coverage_vit_proj_llm_12', 'mico_coverage_vit_proj_llm_10',
                                            'mico_coverage_vit_proj_llm_8', 'mico_coverage_vit_proj_llm_6',
                                            'mico_coverage_vit_proj', 'mico_coverage_proj_llm_12',
                                            'mico_coverage_proj_llm_10', 'mico_coverage_proj_llm_8',
                                            'mico_coverage_proj_llm_7', 'mico_coverage_proj_llm_6', 'mico_coverage_proj') or _is_mico_s1(self.pruning_method):
                    # Same inner raw-CLS×coverage selector. vit_proj*: cosine on
                    # pre-merger ViT; mico_coverage_proj*: cosine on merger output.
                    # Every llm_K arm keeps 2T; single-stage controls keep T.
                    from vlmeval.vlm.mico_coverage_select import inner_weighted_raw_cls_select
                    keep_2t = '_llm_' in self.pruning_method
                    use_vit = 'vit_proj' in self.pruning_method
                    # S1 budget multiple of T. Default 2 keeps every pre-existing
                    # arm bit-identical; the S1 ablation sweeps 3/4/5T.
                    _s1m = int(getattr(self.model, 's1_mult', 2) or 2) if keep_2t else 1
                    stage1_keep_num = min(max(1, self.target_visual_token_num * _s1m), N)
                    if image_attns is not None:
                        if image_attns.dim() == 3:
                            cls_attn = image_attns.mean(dim=1).mean(dim=0)
                        elif image_attns.dim() == 2:
                            cls_attn = image_attns.mean(dim=0)
                        else:
                            cls_attn = image_attns
                    else:
                        cls_attn = image_embeds.norm(dim=-1)
                    if use_vit:
                        vit_feat = getattr(self, '_mmtok_merger_in', None)
                        if vit_feat is not None and vit_feat.shape[0] // 4 == N:
                            _wi, _ = self.visual.get_window_index(image_grid_thw)
                            _rev = torch.argsort(_wi)
                            cov_feat = vit_feat.float().reshape(vit_feat.shape[0] // 4, 4, -1).mean(dim=1)[_rev, :]
                            _covsrc = 'vit'
                        else:
                            cov_feat = image_embeds.float()
                            _covsrc = 'proj(fallback)'
                    else:
                        cov_feat = image_embeds.float()
                        _covsrc = 'proj'
                    mico = _is_mico_s1(self.pruning_method)
                    selected_masks = inner_weighted_raw_cls_select(
                        cov_feat, cls_attn, stage1_keep_num, mico=mico
                    )
                    s2 = f"S2={self.model.pruning_layers}, avg T" if keep_2t else "no LLM prune"
                    print(
                        f"[{self.pruning_method}] S1 raw_visual_attn{'*|h|' if mico else ''}*coverage cov_space={_covsrc}: "
                        f"N={N} → keep {int(selected_masks.sum().item())} "
                        f"({f'{_s1m}T' if keep_2t else 'T'}={stage1_keep_num}, {s2})"
                    )
                elif self.pruning_method == 'apet':
                    from .modeling_qwen2_5_vl_apet import apet_merge_vit_groups
                    stage1_keep_num = min(max(1, self.model.stage1_keep_tokens), N)
                    if stage1_keep_num < N and stage1_keep_num > 1:
                        basis = min(self.model.basis, stage1_keep_num - 1)
                        window_index, _ = self.visual.get_window_index(image_grid_thw)
                        if window_index.numel() != N:
                            raise ValueError('ApET window ordering does not match image-token count')
                        image_embeds, keep = apet_merge_vit_groups(
                            self._mmtok_merger_in, window_index, self.visual.merger,
                            self.visual.spatial_merge_unit, stage1_keep_num, basis, seed=None)
                        selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                        selected_masks[keep] = True
                        print(f"[ApET S1] N={N} -> keep {int(selected_masks.sum().item())} "
                              f"(3T/2={stage1_keep_num}, basis={basis}, "
                              "space=pre-merger-ViT-groups, precision=fp32-merge)")
                    else:
                        print(f"[ApET S1] N={N} -> keep {N} "
                              f"(3T/2={stage1_keep_num}, basis={self.model.basis}, "
                              "space=pre-merger-ViT-groups, mode=dense)")
                elif self.pruning_method == 'cover_prune_3':
                    # COVER_Prune_3 阶段1: 内(每项乘被覆盖token cls_attn)外(乘候选自身cls_attn)都乘, 选 target×2
                    # score(i) = cls_attn(i) · Σ_v cls_attn(v)·max(0, sim(v,i)-g_v)
                    stage1_keep_num = min(max(1, self.target_visual_token_num * 2), N)
                    if image_attns is not None:
                        if image_attns.dim() == 3:
                            cls_attn = image_attns.mean(dim=1).mean(dim=0)
                        elif image_attns.dim() == 2:
                            cls_attn = image_attns.mean(dim=0)
                        else:
                            cls_attn = image_attns
                    else:
                        cls_attn = image_embeds.norm(dim=-1)
                    cls_attn = (cls_attn - cls_attn.min()) / (cls_attn.max() - cls_attn.min() + 1e-8)  # [0,1]
                    image_normalized = image_embeds / (image_embeds.norm(dim=-1, keepdim=True) + 1e-8)
                    sim = torch.clamp(torch.matmul(image_normalized, image_normalized.t()), min=0.0)
                    avail = torch.ones(N, dtype=torch.bool, device=device)
                    selected = []
                    g = torch.zeros(N, device=device)
                    cov0 = cls_attn * (cls_attn.unsqueeze(0) * sim).sum(dim=1)   # 内外都乘
                    i0 = int(torch.argmax(cov0).item())
                    selected.append(i0); avail[i0] = False; g = torch.maximum(g, sim[i0])
                    for _ in range(1, stage1_keep_num):
                        if not avail.any(): break
                        inner = (cls_attn.unsqueeze(0) * torch.clamp(sim - g.unsqueeze(0), min=0.0)).sum(dim=1)
                        scores = cls_attn * inner                                # 外面再乘候选自身attn
                        scores[~avail] = -float('inf')
                        j = int(torch.argmax(scores).item())
                        selected.append(j); avail[j] = False; g = torch.maximum(g, sim[j])
                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[torch.tensor(selected, device=device, dtype=torch.long)] = True
                    print(f"[COVER_Prune_3 S1] cls_attn(i)·Σcls_attn(v)·cov: N={N} → keep {int(selected_masks.sum().item())} (target×2={stage1_keep_num})")
                elif self.pruning_method in ('tops', 'tops_2', 'tops_plus'):
                    # Coverage (C): avg cosine similarity to unselected set
                    import os
                    a1 =  float(os.environ.get("A1",  "1.0"))
                    alpha_1  = float(os.environ.get("ALPHA_1",  "1.0"))
                    lambda_1 = float(os.environ.get("LAMBDA_1", "1.0"))
                    coverage_method = os.environ.get("COVERAGE", "MEAN")

                    # tops_2 (single-stage): prune directly to target (NOT target×2).
                    if self.pruning_method in ('tops_2', 'tops_plus'):
                        stage1_keep_num = min(max(1, self.target_visual_token_num), N)
                    else:
                        stage1_keep_num = min(max(1, self.target_visual_token_num * 2), N)

                    print(f"\n{'='*80}")
                    print(f"[TOPS Stage 1] Vision-Side RDC Greedy Selection ({self.pruning_method})")
                    print(f"  Visual tokens: {N}, Stage1 target: {stage1_keep_num}")
                    print(f"  a1={a1} , alpha_1={alpha_1}, lambda_1={lambda_1}")

                    # ── Relevance: CLS attention ──
                    if image_attns is not None:
                        print(f"[DEBUG][TOPS][tops stage1] image_attns: {image_attns.shape}, dim={image_attns.dim()}")
                        if image_attns.dim() == 3:
                            cls_attn = image_attns.mean(dim=1).mean(dim=0)  # (N,)
                        elif image_attns.dim() == 2:
                            cls_attn = image_attns.mean(dim=0)              # (N,)
                        else:
                            cls_attn = image_attns                          # (N,)
                    else:
                        print("[TOPS S1] Warning: image_attns is None, using L2-norm fallback")
                        cls_attn = image_embeds.norm(dim=-1)                # (N,)
                    print(f"[DEBUG][TOPS][tops stage1] cls_attn: {cls_attn.shape}, N={N}")

                    # Normalize relevance to [0, 1]
                    cls_attn = (cls_attn - cls_attn.min()) / (cls_attn.max() - cls_attn.min() + 1e-8)

                    # ── tops+ merge-first: RDC 前做自适应多轮 bipartite 近重复合并(参数无关,向量化) ──
                    # 轮数 R=round(log2(N/(2·target))) 由N/target自动导出(轻剪枝R小,重剪枝R大);
                    # 每轮交替分A/B,A→最相似B按aff²融合成质心,A与其B共享→RDC的diversity自动跳过重复。
                    # 目标: 合并到 ~2×target 个distinct(VisionZip验证的操作点),RDC再选恰好target。
                    # 设 TOPS_PLUS_FIRST=1 开启; TOPS_PLUS_ROUNDS 可覆盖轮数(默认自适应)。
                    if self.pruning_method == 'tops_plus' and os.environ.get("TOPS_PLUS_FIRST", "0") == "1":
                        import math as _math
                        tgt = max(1, self.target_visual_token_num)
                        R_env = os.environ.get("TOPS_PLUS_ROUNDS", "")
                        if R_env != "":
                            R = int(R_env)
                        else:
                            # 合并到 ~1×target 候选池 (实测 T256 R=2 优于 R=1, 公式给 T256→2/T128→3)
                            R = max(1, int(round(_math.log2(max(2.0, N / max(1.0, float(tgt)))))))
                        image_embeds = image_embeds.clone()
                        for _r in range(R):
                            fn = image_embeds / (image_embeds.norm(dim=-1, keepdim=True) + 1e-8)
                            simfull = torch.matmul(fn, fn.t())
                            idxA = torch.arange(0, N, 2, device=device)
                            idxB = torch.arange(1, N, 2, device=device)
                            if idxA.numel() == 0 or idxB.numel() == 0:
                                break
                            simAB = simfull[idxA][:, idxB]                      # (|A|,|B|)
                            bestB = simAB.argmax(dim=1)                         # (|A|,) -> local B idx
                            aff = simAB.max(dim=1).values.clamp(min=0.0).float()
                            w = aff * aff                                       # aff² 自动只融近重复
                            newB = image_embeds[idxB].clone().float()
                            wsumB = torch.ones(idxB.shape[0], device=device)
                            newB.index_add_(0, bestB, w.unsqueeze(-1) * image_embeds[idxA].float())
                            wsumB.index_add_(0, bestB, w)
                            newB = newB / wsumB.unsqueeze(-1).clamp(min=1e-6)
                            image_embeds[idxB] = newB.to(image_embeds.dtype)
                            image_embeds[idxA] = newB[bestB].to(image_embeds.dtype)  # A与其B共享质心
                        print(f"[tops+FIRST] {R}-round bipartite pre-merge: N={N} -> ~{N//(2**R)} distinct (aff², target={tgt})")

                    # ── Cosine similarity matrix ──
                    print(f"[DEBUG][TOPS][tops stage1] image_embeds: {image_embeds.shape}")
                    feat_n = image_embeds / (image_embeds.norm(dim=-1, keepdim=True) + 1e-8)  # (N, D)
                    sim = torch.matmul(feat_n, feat_n.t())  # (N, N)

                    # ── RDC greedy selection ──
                    avail = torch.ones(N, dtype=torch.bool, device=device)
                    selected = []

                    # Seed: highest relevance token
                    i0 = torch.argmax(cls_attn).item()
                    selected.append(i0)
                    avail[i0] = False
                    max_sim_to_S = sim[i0].clone()
                    max_sim_to_S[i0] = 1.0

                    for _ in range(1, stage1_keep_num):
                        if not avail.any():
                            break

                        diversity = 1.0 - max_sim_to_S

                        # Coverage
                        if coverage_method == "SCOPE":
                            # SCOPE: marginal coverage gain — coverage(i) = sum_j max(0, sim(i,j) - max_sim_to_S[j])
                            coverage = torch.clamp(sim - max_sim_to_S.unsqueeze(0), min=0.0).sum(dim=1)
                            coverage[~avail] = 0.0
                        else:
                            # MEAN: avg similarity to remaining unselected tokens
                            sim_to_avail = sim[:, avail].sum(dim=1)
                            n_avail = avail.sum().item()
                            if n_avail > 1:
                                coverage = (sim_to_avail - 1.0) / (n_avail - 1)
                            else:
                                coverage = torch.zeros(N, device=device)

                        a_mean   = cls_attn.mean().clamp(min=1e-8)
                        div_mean = diversity.mean().clamp(min=1e-8)
                        cov_mean = coverage.mean().clamp(min=1e-8)

                        scores = a1 * (cls_attn / a_mean) + \
                                 alpha_1 * (diversity / div_mean) + \
                                 lambda_1 * (coverage / cov_mean)
                        scores[~avail] = -float("inf")
                        idx = torch.argmax(scores).item()

                        selected.append(idx)
                        avail[idx] = False
                        max_sim_to_S = torch.maximum(max_sim_to_S, sim[idx])
                        max_sim_to_S[idx] = 1.0

                    selected_tensor = torch.tensor(selected, device=device, dtype=torch.long)
                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[selected_tensor] = True

                    # ── tops+ : ToMe-style merge-back (training-free) ──
                    # 每个被剪掉的 token 归并到与它最相似的保留 token, 保留 token 变成
                    # 自身 + 归并邻居的加权融合 (merge 而非硬 drop, 不丢信息)。
                    # 用已算好的 sim(N,N, 余弦) 做 bipartite 分配, env 可调:
                    #   TOPS_PLUS_MERGE=0 关闭; TOPS_PLUS_BETA 融合强度; TOPS_PLUS_WEIGHT sim|attn|uniform
                    if self.pruning_method == 'tops_plus' and os.environ.get("TOPS_PLUS_MERGE", "1") == "1":
                        # ── 新方法 CRM: Coverage-Residual Merge (参数无关,向量化,范数保持) ──
                        # 吸收被剪token相对锚点的"正交残差"(未被覆盖的新信息)而非冗余相似部分。
                        # merged_i = normalize(emb_i + Σ_{j→i} aff_j·r_j) 到 ||emb_i||, r_j=emb_j⊥emb_i。
                        # 设 TOPS_PLUS_CRM=1 启用(优先于PF)。
                        if os.environ.get("TOPS_PLUS_CRM", "0") == "1":
                            sel_idx = selected_tensor
                            pruned_idx = (~selected_masks).nonzero().squeeze(-1)
                            if pruned_idx.numel() > 0:
                                sim_ps = sim[pruned_idx][:, sel_idx]               # (P,K)
                                assign = sim_ps.argmax(dim=1)                      # (P,)
                                aff = sim_ps.max(dim=1).values.clamp(min=0.0).float()
                                pe = image_embeds[pruned_idx].float()             # (P,D)
                                anc = image_embeds[sel_idx][assign].float()       # (P,D) 每个pruned的锚点
                                anc_hat = anc / (anc.norm(dim=-1, keepdim=True) + 1e-8)
                                proj = (pe * anc_hat).sum(dim=-1, keepdim=True) * anc_hat  # j在锚点方向的投影
                                resid = pe - proj                                 # (P,D) 正交残差=新信息
                                contrib = aff.unsqueeze(-1) * resid               # 按区域归属加权
                                K = sel_idx.shape[0]
                                acc = torch.zeros(K, pe.shape[1], device=device, dtype=torch.float32)
                                acc.index_add_(0, assign, contrib)
                                orig = image_embeds[sel_idx].float()
                                v = orig + acc
                                # 范数保持(ToFu MLERP思想): 缩放回原范数,防分布漂移
                                v = v * (orig.norm(dim=-1, keepdim=True) / (v.norm(dim=-1, keepdim=True) + 1e-8))
                                image_embeds = image_embeds.clone()
                                image_embeds[sel_idx] = v.to(image_embeds.dtype)
                                print(f"[tops+CRM] residual-injected {pruned_idx.numel()} pruned -> {K} kept (norm-preserved)")
                            print(f"  Selected {selected_masks.sum().item()} tokens")
                            print(f"{'='*80}\n")
                        else:
                            # ── 参数无关定稿版 (PF): affinity² 加权融合, 零调参+全向量化 ──
                            # merged_i = (emb_i + Σ_{j→i} aff_j²·emb_j) / (1 + Σ_{j→i} aff_j²)
                            # aff² 自动压制远处token(近重复主导), 无 beta/threshold/protect。
                            # 默认走 PF; 设 TOPS_PLUS_PF=0 回退到带参诊断版(beta/simthr/protect)。
                            pf = os.environ.get("TOPS_PLUS_PF", "1") == "1"
                            sel_idx = selected_tensor                                  # (K,)
                            pruned_idx = (~selected_masks).nonzero().squeeze(-1)       # (P,)
                            if pf:
                                if pruned_idx.numel() > 0:
                                    sim_ps = sim[pruned_idx][:, sel_idx]               # (P,K)
                                    assign = sim_ps.argmax(dim=1)                      # (P,)
                                    aff = sim_ps.max(dim=1).values.clamp(min=0.0).float()
                                    w = aff * aff                                      # affinity² 自动门控
                                    merged = image_embeds[sel_idx].clone().float()
                                    wsum = torch.ones(sel_idx.shape[0], device=device)
                                    pe = image_embeds[pruned_idx].float()
                                    merged.index_add_(0, assign, w.unsqueeze(-1) * pe)
                                    wsum.index_add_(0, assign, w)
                                    merged = merged / wsum.unsqueeze(-1).clamp(min=1e-6)
                                    image_embeds = image_embeds.clone()
                                    image_embeds[sel_idx] = merged.to(image_embeds.dtype)
                                    print(f"[tops+PF] merged {pruned_idx.numel()} pruned -> {sel_idx.shape[0]} kept (aff²)")
                    if self.pruning_method == 'tops_plus' and os.environ.get("TOPS_PLUS_MERGE","1")=="1" and os.environ.get("TOPS_PLUS_PF","1")=="0":
                        beta = float(os.environ.get("TOPS_PLUS_BETA", "0.5"))
                        wmode = os.environ.get("TOPS_PLUS_WEIGHT", "sim")
                        simthr = float(os.environ.get("TOPS_PLUS_SIMTHR", "0.0"))  # 仅融合相似度>=阈值的近重复token
                        sel_idx = selected_tensor                                  # (K,)
                        pruned_idx = (~selected_masks).nonzero().squeeze(-1)       # (P,)
                        if pruned_idx.numel() > 0 and beta > 0:
                            # 每个 pruned token -> 最相似的 selected token
                            sim_ps = sim[pruned_idx][:, sel_idx]                   # (P, K)
                            assign = sim_ps.argmax(dim=1)                          # (P,) -> local sel index
                            aff = sim_ps.max(dim=1).values.clamp(min=0.0).float()  # (P,) 相似度
                            if wmode == "attn":
                                w = cls_attn[pruned_idx].clamp(min=0.0).float()
                            elif wmode == "uniform":
                                w = torch.ones_like(aff)
                            else:  # sim
                                w = aff
                            if simthr > 0.0:
                                # 阈值门控: 相似度低于阈值的 pruned token 不融合(权重置0),避免稀释保留token
                                w = w * (aff >= simthr).float()
                            # relevance-protect: 保护高relevance保留token纯净(细粒度任务),
                            # 只让低relevance保留token吸收被剪token。protect_top=保护比例。
                            protect_top = float(os.environ.get("TOPS_PLUS_PROTECT_TOP", "0.0"))
                            if protect_top > 0.0:
                                K = sel_idx.shape[0]
                                n_prot = int(protect_top * K)
                                if n_prot > 0:
                                    sel_rel = cls_attn[sel_idx]                        # (K,) 保留token的relevance
                                    prot_local = sel_rel.topk(n_prot).indices          # 高relevance的局部下标
                                    prot_mask = torch.zeros(K, dtype=torch.bool, device=device)
                                    prot_mask[prot_local] = True
                                    # pruned token 若被分配到受保护的sel token, 权重置0(不融合)
                                    w = w * (~prot_mask[assign]).float()
                            merged = image_embeds[sel_idx].clone().float()         # (K,D)
                            wsum = torch.ones(sel_idx.shape[0], device=device)     # 自身权重=1
                            pe = image_embeds[pruned_idx].float()                  # (P,D)
                            merged.index_add_(0, assign, beta * w.unsqueeze(-1) * pe)
                            wsum.index_add_(0, assign, beta * w)
                            merged = merged / wsum.unsqueeze(-1).clamp(min=1e-6)
                            image_embeds = image_embeds.clone()
                            image_embeds[sel_idx] = merged.to(image_embeds.dtype)
                            print(f"[tops+] merged {pruned_idx.numel()} pruned -> {sel_idx.shape[0]} kept "
                                  f"(beta={beta}, w={wmode})")

                    print(f"  Selected {selected_masks.sum().item()} tokens")
                    print(f"{'='*80}\n")

                self.visual_token_len = selected_masks.sum().item()

                n_image_tokens = (input_ids == self.config.image_token_id).sum().item()
                n_image_features = image_embeds.shape[0]
                if n_image_tokens != n_image_features:
                    raise ValueError(
                        f"Image features and image tokens do not match: tokens: {n_image_tokens}, features {n_image_features}"
                    )

                mask = input_ids == self.config.image_token_id
                if self.pruning_method == 'apet':
                    # ApET S2 needs the exact visual span after S1 to merge mid-decoder.
                    if mask.shape[0] != 1 or selected_masks.ndim != 1 or selected_masks.dtype != torch.bool:
                        raise ValueError('apet requires one image-token sequence and a 1D bool S1 mask')
                    image_positions = mask[0].nonzero().squeeze(-1)
                    if image_positions.numel() == 0 or selected_masks.numel() != image_positions.numel():
                        raise ValueError('apet S1 mask must align with the actual image-token span')
                    visual_start = int(image_positions[0].item())
                    if not torch.equal(image_positions, torch.arange(
                            visual_start, visual_start + image_positions.numel(), device=image_positions.device)):
                        raise ValueError('apet requires a contiguous image-token span')
                    stage1_metadata['stage1_visual_span'] = (visual_start, int(selected_masks.sum().item()))
                if self.pruning_method in ('mico_coverage_vit_proj_llm_12', 'mico_coverage_vit_proj_llm_10',
                                           'mico_coverage_vit_proj_llm_8', 'mico_coverage_vit_proj_llm_6',
                                           'mico_coverage_proj_llm_12', 'mico_coverage_proj_llm_10',
                                           'mico_coverage_proj_llm_8', 'mico_coverage_proj_llm_7',
                                           'mico_coverage_proj_llm_6') or _is_mico(self.pruning_method):
                    # Short OCR inputs may keep every visual token; their text suffix is not always 10 tokens.
                    if mask.shape[0] != 1 or selected_masks.ndim != 1 or selected_masks.dtype != torch.bool:
                        raise ValueError('mico_coverage LLM pruning requires one image-token sequence and a 1D bool S1 mask')
                    image_positions = mask[0].nonzero().squeeze(-1)
                    if image_positions.numel() == 0 or selected_masks.numel() != image_positions.numel():
                        raise ValueError('S1 mask must align with the actual image-token span')
                    visual_start = int(image_positions[0].item())
                    if not torch.equal(image_positions, torch.arange(
                            visual_start, visual_start + image_positions.numel(), device=image_positions.device)):
                        raise ValueError('mico_coverage LLM pruning requires a contiguous image-token span')
                    stage1_metadata['stage1_visual_span'] = (visual_start, int(selected_masks.sum().item()))
                mask_unsqueezed = mask.unsqueeze(-1)
                mask_expanded = mask_unsqueezed.expand_as(inputs_embeds)
                image_mask = mask_expanded.to(inputs_embeds.device)

                image_embeds = image_embeds.to(inputs_embeds.device, inputs_embeds.dtype)
                inputs_embeds = inputs_embeds.masked_scatter(image_mask, image_embeds)

                # FastV's legacy 15/1296 constants only describe one image shape. Rebuild this
                # sample's contiguous image span here, where mask and image_embeds are aligned.
                if self.pruning_method in ('fastv', 'dart', 'dart_coverage', 'cover_llm', 'sparsevlm'):
                    _mrow = mask[0] if mask.dim() == 2 else mask
                    _vis_pos = _mrow.nonzero().reshape(-1)
                    if _vis_pos.numel() == 0:
                        raise ValueError(f'{self.pruning_method} received image features without image tokens')
                    _vis_start = int(_vis_pos[0].item())
                    if not torch.equal(
                        _vis_pos,
                        torch.arange(_vis_start, _vis_start + _vis_pos.numel(), device=_vis_pos.device),
                    ):
                        # FastV has a scalar start/length interface, so a discontiguous span would
                        # otherwise make it prune text tokens instead of image tokens.
                        raise ValueError(f'{self.pruning_method} requires one contiguous image-token span')
                    self.model.system_prompt_length = _vis_start
                    self.model.visual_token_length = int(_vis_pos.numel())

            if pixel_values_videos is not None:
                pixel_values_videos = pixel_values_videos.type(self.visual.dtype)
                video_embeds = self.visual(pixel_values_videos, grid_thw=video_grid_thw)
                n_video_tokens = (input_ids == self.config.video_token_id).sum().item()
                n_video_features = video_embeds.shape[0]
                if n_video_tokens != n_video_features:
                    raise ValueError(
                        f"Video features and video tokens do not match: tokens: {n_video_tokens}, features {n_video_features}"
                    )

                mask = input_ids == self.config.video_token_id
                mask_unsqueezed = mask.unsqueeze(-1)
                mask_expanded = mask_unsqueezed.expand_as(inputs_embeds)
                video_mask = mask_expanded.to(inputs_embeds.device)

                video_embeds = video_embeds.to(inputs_embeds.device, inputs_embeds.dtype)
                inputs_embeds = inputs_embeds.masked_scatter(video_mask, video_embeds)

            if attention_mask is not None:
                attention_mask = attention_mask.to(inputs_embeds.device)

        # if we get 4D attention mask we cannot calculate rope deltas anymore. TODO @raushan fixme
        if position_ids is None and (attention_mask is None or attention_mask.ndim == 2):
            # calculate RoPE index once per generation in the pre-fill stage only
            if (
                (cache_position is not None and cache_position[0] == 0)
                or self.rope_deltas is None
                or (past_key_values is None or past_key_values.get_seq_length() == 0)
            ):
                # generate() grows its mask from this unpruned prompt, so keep this
                # boundary immutable and reset any index state from the previous sample.
                self._orig_prompt_len = int(inputs_embeds.shape[1])
                self.retain_token_indices = None
                position_ids, rope_deltas = self.model.get_rope_index(
                    input_ids,
                    image_grid_thw,
                    video_grid_thw,
                    second_per_grid_ts,
                    attention_mask,
                )
                self.rope_deltas = rope_deltas

                # Select visual tokens using `selected_masks`
                if selected_masks.sum() < selected_masks.numel():
                    system_prompt_length = int(mask.max(dim=-1).indices)
                    visual_token_length = selected_masks.shape[0]
                    visual_token_indices = selected_masks.nonzero().squeeze(-1)
                    retain_token_indices = torch.cat((
                        torch.arange(system_prompt_length, device=device),
                        visual_token_indices + system_prompt_length,
                        torch.arange(system_prompt_length+visual_token_length, inputs_embeds.shape[1], device=device),
                    ))
                    print(f"[TOPS-Variant3 Stage1] retain_token_indices length = {retain_token_indices.shape[0]}")
                    self.retain_token_indices = retain_token_indices

                    inputs_embeds = inputs_embeds[:, retain_token_indices]
                    position_ids = position_ids[:, :, retain_token_indices]
                    attention_mask = attention_mask[:, retain_token_indices]
                    cache_position = cache_position[:retain_token_indices.shape[0]]

            # then use the prev pre-calculated rope-deltas to get the correct position ids
            else:
                batch_size, seq_length, _ = inputs_embeds.shape
                delta = (
                    (cache_position[0] + self.rope_deltas).to(inputs_embeds.device)
                    if cache_position is not None
                    else 0
                )
                position_ids = torch.arange(seq_length, device=inputs_embeds.device)
                position_ids = position_ids.view(1, -1).expand(batch_size, -1)
                if cache_position is not None:  # otherwise `deltas` is an int `0`
                    delta = delta.repeat_interleave(batch_size // delta.shape[0], dim=0)
                position_ids = position_ids.add(delta)
                position_ids = position_ids.unsqueeze(0).expand(3, -1, -1)

                # Rebuild the decoded tail from the immutable prefill boundary. Mutating
                # retain_token_indices here makes later decode steps depend on their history.
                retain_token_indices = getattr(self, 'retain_token_indices', None)
                if attention_mask is not None and retain_token_indices is not None:
                    tail_indices = torch.arange(
                        self._orig_prompt_len,
                        attention_mask.shape[1],
                        device=attention_mask.device,
                        dtype=retain_token_indices.dtype,
                    )
                    attention_mask = attention_mask[:, torch.cat((
                        retain_token_indices.to(attention_mask.device), tail_indices,
                    ))]

        # FastV/DART: the current image span is set at the aligned scatter point above.

        outputs = self.model(
            input_ids=None,
            position_ids=position_ids,
            attention_mask=attention_mask,
            past_key_values=past_key_values,
            inputs_embeds=inputs_embeds,
            use_cache=use_cache,
            output_attentions=output_attentions,
            output_hidden_states=output_hidden_states,
            return_dict=return_dict,
            cache_position=cache_position,
            **stage1_metadata,
        )

        hidden_states = outputs[0]
        logits = self.lm_head(hidden_states)

        loss = None
        if labels is not None:
            # Upcast to float if we need to compute the loss to avoid potential precision issues
            logits = logits.float()
            # Shift so that tokens < n predict n
            shift_logits = logits[..., :-1, :].contiguous()
            shift_labels = labels[..., 1:].contiguous()
            # Flatten the tokens
            loss_fct = CrossEntropyLoss()
            shift_logits = shift_logits.view(-1, self.config.vocab_size)
            shift_labels = shift_labels.view(-1)
            # Enable model parallelism
            shift_labels = shift_labels.to(shift_logits.device)
            loss = loss_fct(shift_logits, shift_labels)

        if not return_dict:
            output = (logits,) + outputs[1:]
            return (loss,) + output if loss is not None else output

        return Qwen2_5_VLCausalLMOutputWithPast(
            loss=loss,
            logits=logits,
            past_key_values=outputs.past_key_values,
            hidden_states=outputs.hidden_states,
            attentions=outputs.attentions,
            rope_deltas=self.rope_deltas,
        )
